/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A38 staging source: exact 80-lemma frozen manifest; publish audited checkpoints only. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});

D('geothermal',{etymology:E('Geothermal combines geo-, from Greek ge “earth,” and thermal, from Greek thermos “warm.” It describes heat originating inside the Earth.','geothermal'),contexts:[C('geothermal.s1','地热供能','The town’s geothermal system draws heat from deep underground to warm public buildings through the winter.','这座小镇的地热系统从地下深处获取热量，为公共建筑供暖过冬。','The town’s geothermal system draws heat from deep underground / to warm public buildings / through the winter.','geothermal 修饰 system，指利用或来自地球内部热量。','地下热能用于供暖，符合地热义。')],mistakes:[M('The geothermal plant gets its heat from sunlight reflected off the roof, not from underground.','The solar plant gets its heat from sunlight reflected off the roof.','依靠阳光而非地球内部热量，不属于 geothermal。')],quiz:[Q('geothermal',1,1,'Geothermal energy comes from?','heat inside the Earth','wind over the ocean','burning paper','heat inside the Earth','geo 指地球，thermal 指热，合起来是地热。'),Q('geothermal',2,1,'A geothermal heating system may use?','heat drawn from underground','cold air stored in a freezer','coal delivered by ship only','heat drawn from underground','系统利用地下热能供暖。'),Q('geothermal',3,1,'Which source is geothermal?','a hot underground reservoir','a rooftop solar panel','a moving river current','a hot underground reservoir','地下热水属于地热资源。'),Q('geothermal',4,1,'The word geothermal combines ideas of?','Earth and heat','glass and water','ghost and light','Earth and heat','词源由 geo-“地球”和 thermal“热”组成。','word-formation')]});
D('geothermally',{etymology:E('Geothermally is formed from geothermal plus -ly. It means by using heat from inside the Earth.','geothermally'),contexts:[C('geothermally.s1','温室供暖','The greenhouse is heated geothermally, with pipes carrying warmth from a shallow underground loop beneath the greenhouse floor.','温室采用地热供暖，管道把温暖从温室地板下的浅层地下循环系统输送上来。','The greenhouse is heated geothermally / with pipes carrying warmth / from a shallow underground loop / beneath the greenhouse floor.','geothermally 是副词，修饰 heated，表示通过地热方式。','热量来自地下循环系统，符合用地热地。')],mistakes:[M('The building is heated geothermally by burning only diesel fuel in a rooftop generator.','The building is heated with diesel fuel by burning it in a rooftop generator.','单靠燃烧柴油供热不是 geothermally。')],quiz:[Q('geothermally',1,1,'A building heated geothermally gets warmth?','from the Earth’s internal heat','from an open refrigerator','from a paper lantern','from the Earth’s internal heat','geothermally 表示使用地热。'),Q('geothermally',2,1,'Which source would heat a home geothermally?','an underground heat loop','a coal stove in the living room','a rooftop fan','an underground heat loop','地下热循环是地热供暖方式。'),Q('geothermally',3,1,'In “powered geothermally,” the adverb tells?','the energy source or method','the building’s colour','the number of rooms','the energy source or method','副词说明供能方式。'),Q('geothermally',4,1,'Choose a compatible pair.','geothermally heated pool','geothermally chilled coal','geothermally painted door','geothermally heated pool','地热可以用于加热泳池。')]});
D('geothermic',{etymology:E('Geothermic combines geo-, “Earth,” and thermic, “relating to heat.” It means relating to heat within the Earth; geothermal is the more usual everyday form.','geothermic'),contexts:[C('geothermic.s1','地球物理','The report compared geothermic gradients across the volcanic field, noting where temperatures rose most rapidly with depth.','报告比较了火山区各处的地温梯度，并指出哪些地方的温度随深度上升最快。','The report compared geothermic gradients / across the volcanic field / noting where temperatures rose most rapidly / with depth.','geothermic 修饰 gradients，指与地球内部热量有关。','测量深度和地温变化正是地热研究内容。')],mistakes:[M('The geothermic survey measured only surface wind speed and recorded no underground temperatures.','The meteorological survey measured surface wind speed without recording underground temperatures.','只测风速没有研究地热，不能称 geothermic survey。')],quiz:[Q('geothermic',1,1,'A geothermic gradient concerns?','how temperature changes with depth inside Earth','how fast clouds cross the sky','how glass cools in a freezer','how temperature changes with depth inside Earth','geothermic 指地球内部的热现象。'),Q('geothermic',2,1,'A geothermic study is most likely conducted by?','a geophysicist studying underground heat','a tailor measuring cloth','a chef tasting soup','a geophysicist studying underground heat','地球物理学家会研究地温。'),Q('geothermic',3,1,'Which topic is geothermic?','heat flow beneath a volcanic region','the colour of a flag','the spelling of a French noun','heat flow beneath a volcanic region','地下热流与地热有关。'),Q('geothermic',4,1,'Geothermic and geothermal both relate to?','heat from within the Earth','cold air from space','animal fur','heat from within the Earth','两词都表示与地球热量有关。')]});
D('German',{etymology:E('German comes from Latin Germanus, the Roman name for a member of the Germanic peoples. In modern English it can refer to a person, the language, or something relating to Germany.','German'),contexts:[C('German.s2','语言课程','The students studied German for a year before travelling through Austria, where they used the language to ask for directions.','学生们先学了一年德语，然后前往奥地利旅行，并用这种语言问路。','The students studied German for a year / before travelling through Austria / where they used the language / to ask for directions.','German 作语言名时首字母大写。','句中明确把 German 当作交流语言，符合 s2。')],mistakes:[M('She learned German to speak with locals, but wrote the language name as german in her report.','She learned German to speak with locals and capitalized the language name in her report.','语言专名 German 首字母必须大写。','capitalization')],quiz:[Q('German',1,1,'A German is?','a person from Germany or of German origin','a type of geothermal plant','a glassmaking tool','a person from Germany or of German origin','s1 指德国人。'),Q('German',2,2,'She speaks German. Here German is?','a language','a country','a nationality only','a language','s2 指德语。'),Q('German',3,3,'German architecture means architecture?','related to Germany or its culture','made only of glass','built underground for heat','related to Germany or its culture','s3 表示德国的、与德国有关的。'),Q('German',4,2,'Which spelling is correct for the language?','German','german','Germane','German','语言名 German 要大写。','capitalization')]});
D('germane',{etymology:E('Germane came from Latin germanus “having the same parents, related,” through French. Its modern sense is “closely relevant” to the matter under discussion.','germane'),contexts:[C('germane.s1','会议讨论','The chair asked each witness to keep comments germane to the safety review, rather than turning the hearing into a debate about parking fees.','主席要求每位证人只谈与安全审查密切相关的内容，不要把听证会变成停车费辩论。','The chair asked each witness to keep comments germane to the safety review / rather than turning the hearing / into a debate about parking fees.','germane 常与 to 连用，表示与某事密切相关。','证词需切合安全审查主题，符合义项。')],mistakes:[M('The witness’s comments about the committee’s lunch menu were germane to the bridge’s structural safety.','The witness’s comments about the bridge’s supports were germane to its structural safety.','午餐菜单与桥梁结构安全无关。')],quiz:[Q('germane',1,1,'A germane point in a debate is?','closely relevant to the issue','about an unrelated topic','a type of German food','closely relevant to the issue','germane 指切题、密切相关。'),Q('germane',2,1,'Which fact is germane to a bridge inspection?','the condition of its support beams','the inspector’s favourite film','the price of a nearby sandwich','the condition of its support beams','支撑梁状况与桥梁检查直接相关。'),Q('germane',3,1,'Choose the standard preposition.','germane to the question','germane with the question','germane of questionly','germane to the question','常见结构是 germane to。','collocation'),Q('germane',4,1,'If evidence is not germane, it is?','irrelevant to the matter','the strongest proof available','a formal German document','irrelevant to the matter','不 germane 就是不相关。')]});
D('germanium',{etymology:E('Germanium was named in 1886 from Germania, the Latin name for Germany, where the element was identified. The chemical suffix -ium is common in element names.','germanium'),contexts:[C('germanium.s1','半导体材料','The detector uses a germanium crystal to register gamma rays, because the semiconductor can produce a measurable signal when radiation passes through it.','探测器使用锗晶体记录伽马射线，因为辐射通过这种半导体时会产生可测信号。','The detector uses a germanium crystal / to register gamma rays / because the semiconductor can produce a measurable signal / when radiation passes through it.','germanium 是元素名，符号 Ge。','锗晶体作为半导体用于探测辐射，符合定义。')],mistakes:[M('The technician chose germanium because it is an edible grain used to thicken soup.','The technician chose germanium because it is a semiconductor used in electronic detectors.','锗是化学元素，不是可食用谷物。')],quiz:[Q('germanium',1,1,'Germanium is a?','chemical element used as a semiconductor','kind of bread','type of glass curtain','chemical element used as a semiconductor','germanium 是半导体元素锗。'),Q('germanium',2,1,'The chemical symbol for germanium is?','Ge','Gm','Gn','Ge','元素符号 Ge 对应 germanium。'),Q('germanium',3,1,'A germanium crystal might be used in?','a radiation detector','a cloth shirt','a fruit bowl only','a radiation detector','锗的半导体性质可用于探测器。'),Q('germanium',4,1,'The element’s name refers to?','Germany','a gibbon','a geyser','Germany','名称取自拉丁地名 Germania。')]});
D('Germany',{etymology:E('Germany comes from Latin Germania, the Roman name for lands associated with Germanic peoples. It names the central European country and can also refer to its state or national economy.','Germany'),contexts:[C('Germany.s1','地理介绍','Germany lies in central Europe and shares borders with nine countries, including France, Poland, and Austria.','德国位于中欧，与九个国家接壤，其中包括法国、波兰和奥地利。','Germany lies in central Europe / and shares borders with nine countries / including France, Poland, and Austria.','Germany 是国家专名，首字母大写。','句中指中欧国家及其疆界。')],mistakes:[M('Germany is a language spoken in Berlin, while German is the country’s capital city.','Germany is the country, German is its language, and Berlin is its capital.','把国家、语言和首都名称混淆。')],quiz:[Q('Germany',1,1,'Germany is a country in?','central Europe','South America','the Pacific Ocean','central Europe','s1 指中欧国家德国。'),Q('Germany',2,2,'A report on Germany as an economic power discusses?','the German state and economy','only the German language’s grammar','a type of mushroom','the German state and economy','s2 把 Germany 作为政治经济实体讨论。'),Q('Germany',3,1,'Which sentence uses Germany correctly?','They travelled across Germany by train.','They spoke Germany at home.','Germany was translated into German.','They travelled across Germany by train.','Germany 是国家名，不是语言名。'),Q('Germany',4,1,'Germany’s capital is?','Berlin','Vienna','Zurich','Berlin','柏林是德国首都。')]});
D('germinate',{etymology:E('Germinate comes from Latin germinare “to bud or sprout,” from germen “bud, shoot.” It describes a seed beginning to grow, causing that growth, or an idea beginning to form.','germinate'),contexts:[C('germinate.s3','创意形成','The idea began to germinate during the field interviews, when several residents independently proposed turning the empty lot into a shared garden.','在实地访谈期间，这个想法开始萌生，因为几位居民独立提出把空地改成共享花园。','The idea began to germinate during the field interviews / when several residents independently proposed / turning the empty lot / into a shared garden.','germinate 在此作不及物动词，比喻想法开始形成。','多人提出方案表明想法逐渐萌生，符合 s3。')],mistakes:[M('The garden plan germinated fully before anyone had thought of it or discussed it.','The garden plan had not yet germinated because nobody had thought of or discussed it.','尚无人想到或讨论的计划还未开始形成。')],quiz:[Q('germinate',1,1,'When a seed germinates, it?','begins to grow','turns into a stone','stops absorbing water forever','begins to grow','s1 指种子开始萌芽。'),Q('germinate',2,2,'To germinate a seed is to?','cause it to start growing','remove all warmth and water','harvest its fruit','cause it to start growing','s2 是及物用法，使种子发芽。'),Q('germinate',3,3,'An idea that germinates?','begins to form in people’s minds','is fully abandoned','is a plant root only','begins to form in people’s minds','s3 比喻指想法萌生。'),Q('germinate',4,1,'Seeds often need moisture and warmth to?','germinate','gibe','gild','germinate','水分与温度有助于种子发芽。')]});
D('germination',{etymology:E('Germination is formed from germinate plus -ion. Germinate comes from Latin germinare “to sprout”; the noun names seed growth or the early formation of an idea.','germination'),contexts:[C('germination.s1','种子实验','The students measured germination by recording how many bean seeds produced visible roots after five days in damp paper.','学生们把豆种放在湿纸上五天，记录长出可见根的种子数量，以此测量发芽情况。','The students measured germination / by recording how many bean seeds / produced visible roots / after five days in damp paper.','germination 是种子开始生长的过程。','可见根的出现是种子发芽的观察指标。')],mistakes:[M('The seeds showed germination even though none opened, sprouted, or produced a root.','The seeds showed no germination because none opened or produced a root.','没有任何萌芽迹象说明种子尚未发芽。')],quiz:[Q('germination',1,1,'Germination is the process in which a seed?','begins to grow and sprout','is ground into flour','is turned into a glass bead','begins to grow and sprout','s1 指种子发芽过程。'),Q('germination',2,2,'The germination of an idea means its?','early development in people’s minds','complete destruction','conversion into a seed','early development in people’s minds','s2 是想法萌生、形成。'),Q('germination',3,1,'What is commonly recorded in a germination test?','how many seeds sprout','the colour of the pot only','the age of the gardener','how many seeds sprout','发芽实验会统计萌芽种子数量。'),Q('germination',4,1,'Germination follows the stage when a seed is?','dormant','a mature fruit','a finished glasswork','dormant','种子结束休眠后可开始萌发。')]});
D('gesso',{etymology:E('Gesso came through Italian gesso “plaster,” from Latin gypsum and Greek gypsos. It is a chalk- or gypsum-based white ground applied to a panel before painting.','gesso'),contexts:[C('gesso.s1','绘画准备','The artist brushed several thin coats of gesso onto the wooden panel and sanded the surface before applying the oil paint.','画家在木板上刷了几层薄石膏底料，并在涂油画颜料前打磨表面。','The artist brushed several thin coats of gesso onto the wooden panel / and sanded the surface / before applying the oil paint.','gesso 是绘画前使用的白色底料。','底料涂在木板上并打磨以备作画，符合定义。')],mistakes:[M('The painter applied gesso as the final coloured varnish after finishing the image.','The painter applied gesso as a white ground before painting the image.','gesso 是绘画底层材料，不是完成后的彩色清漆。')],quiz:[Q('gesso',1,1,'An artist applies gesso to a panel to?','prepare a ground for painting','seal a finished book','make a glass funnel','prepare a ground for painting','gesso 是绘画前的白色底料。'),Q('gesso',2,1,'Gesso commonly contains?','chalk or gypsum with a binder','freshwater fish','cotton threads only','chalk or gypsum with a binder','石膏或白垩混合黏结剂制成底料。'),Q('gesso',3,1,'When is gesso applied?','before paint is added','only after the painting is framed','while the panel is being eaten','before paint is added','底料先涂于画板，再上颜料。'),Q('gesso',4,1,'The Italian source gesso means?','plaster','ghost','gill','plaster','gesso 源自意大利语“石膏”。')]});
D('geyser',{etymology:E('Geyser is borrowed from Icelandic Geysir, the name of a famous erupting spring, from geysa “to gush.” It names a hot spring that intermittently ejects water and steam.','geyser'),contexts:[C('geyser.s1','地热公园','Visitors waited behind the marked boundary as the geyser sent a column of hot water and steam above the basin.','游客在标线后等待，间歇泉随后把一柱热水和蒸汽喷到泉池上方。','Visitors waited behind the marked boundary / as the geyser sent a column of hot water and steam / above the basin.','geyser 指会间歇喷出热水和蒸汽的天然泉。','热水和蒸汽周期性喷发，符合间歇泉义。')],mistakes:[M('The geyser was a cold underground lake that never released water or steam.','The geyser was a hot spring that periodically released water and steam.','不喷出热水或蒸汽的冷湖不是 geyser。')],quiz:[Q('geyser',1,1,'A geyser periodically ejects?','hot water and steam','cold sand and leaves','only dry air','hot water and steam','间歇泉会间歇喷出热水和蒸汽。'),Q('geyser',2,1,'Where would a geyser most likely form?','in a geothermally active region','inside a refrigerator','on a dry paper sheet','in a geothermally active region','地下热活动可加热并驱动泉水喷发。'),Q('geyser',3,1,'The word geyser comes from Icelandic?','Geysir','gibbon','Germanium','Geysir','名称来自冰岛著名喷泉 Geysir。'),Q('geyser',4,1,'Visitors near a geyser should?','stay behind the safety boundary','stand over the vent','drink the erupting water','stay behind the safety boundary','喷发热水危险，应遵守安全边界。')]});
D('ghastly',{etymology:E('Ghastly comes from an older form related to ghost and Old English gast “spirit.” It describes something horrifying or, informally, extremely bad in quality.','ghastly'),contexts:[C('ghastly.s1','事故现场','The rescue team found a ghastly scene after the landslide, with damaged homes and injured residents across the road.','救援队在山体滑坡后看到可怕景象：道路两旁房屋受损，居民受伤。','The rescue team found a ghastly scene after the landslide / with damaged homes / and injured residents / across the road.','ghastly 修饰 scene，表示令人恐惧、震惊。','严重灾害造成的伤亡和破坏构成可怕景象。')],mistakes:[M('The cheerful picnic was ghastly because everyone laughed, ate safely, and enjoyed the sunny afternoon.','The cheerful picnic was delightful because everyone laughed and enjoyed the afternoon.','愉快安全的野餐不符合 ghastly 的可怕或极坏义。')],quiz:[Q('ghastly',1,1,'A ghastly accident scene is?','horrifying to see','pleasant and relaxing','a type of seed','horrifying to see','ghastly 表示可怕、令人震惊。'),Q('ghastly',2,1,'Informally, a ghastly meal may be?','extremely bad','perfectly delicious','a formal dinner award','extremely bad','该词也可口语表示质量极差。'),Q('ghastly',3,1,'Which image is ghastly?','a badly damaged building after a disaster','a bright picnic in a safe garden','a clean empty plate','a badly damaged building after a disaster','严重破坏的场面令人震惊。'),Q('ghastly',4,1,'Ghastly is closest to?','horrible','delightful','ordinary','horrible','horrible 与 ghastly 的可怕义接近。')]});
D('ghostly',{etymology:E('Ghostly is formed from ghost plus -ly, an adjective-forming ending. Ghost comes from Old English gast “spirit.” Ghostly means resembling a ghost, often pale, faint, or eerie.','ghostly'),contexts:[C('ghostly.s1','雾中景象','A ghostly outline of the lighthouse appeared through the fog, then faded as the boat moved farther from shore.','灯塔的朦胧轮廓从雾中显现，随后船驶离岸边时又渐渐消失。','A ghostly outline of the lighthouse appeared through the fog / then faded / as the boat moved farther from shore.','ghostly 修饰 outline，表示像幽灵般模糊、隐约。','轮廓苍白、从雾中出现又消失，带有幽灵般观感。')],mistakes:[M('The ghostly figure was brightly lit, sharply detailed, and completely ordinary in appearance.','The ghostly figure was pale, faint, and eerie in appearance.','清晰明亮且普通的外观与 ghostly 的朦胧诡异特征相反。')],quiz:[Q('ghostly',1,1,'A ghostly shape in the mist looks?','pale, faint, or eerie','solid and brightly coloured','like a fresh loaf','pale, faint, or eerie','ghostly 表示像幽灵般朦胧或诡异。'),Q('ghostly',2,1,'A ghostly voice may sound?','faint and eerie','cheerful and loud like a brass band','exactly like a barking dog','faint and eerie','该词可描述幽灵般的声音效果。'),Q('ghostly',3,1,'Which adjective is closest in atmosphere?','spectral','sunny','ordinary','spectral','spectral 同样有幽灵般的意味。'),Q('ghostly',4,1,'A ghostly outline is usually?','unclear and fading','a sharply carved solid object','a printed colour chart','unclear and fading','模糊消散的轮廓符合 ghostly。')]});
D('gibbon',{etymology:E('Gibbon entered English through French in the eighteenth century as the name of a Southeast Asian ape; its earlier source is uncertain. It is a tailless ape with very long arms adapted for swinging through trees.','gibbon'),contexts:[C('gibbon.s1','野生动物观察','The gibbon swung between branches using its long arms, then called to another member of its group from the canopy.','长臂猿用长臂在树枝间摆荡，随后在树冠层呼唤同群的另一只。','The gibbon swung between branches using its long arms / then called to another member / of its group / from the canopy.','gibbon 是无尾类人猿，长臂适于树间摆荡。','长臂摆荡和树冠生活符合长臂猿特征。')],mistakes:[M('The gibbon moved through the trees using a long tail and short arms.','The gibbon moved through the trees using long arms and no tail.','长臂猿没有尾巴，且以长臂摆荡。')],quiz:[Q('gibbon',1,1,'A gibbon is a?','tailless ape with very long arms','small tailed fish','kind of glassware','tailless ape with very long arms','gibbon 指长臂猿。'),Q('gibbon',2,1,'A gibbon moves through trees mainly by?','swinging with its long arms','crawling underground','using wings to fly','swinging with its long arms','长臂有助于树间摆荡。'),Q('gibbon',3,1,'Which feature distinguishes a gibbon from a monkey with a tail?','it has no tail','it has feathers','it lives only underwater','it has no tail','长臂猿无尾。'),Q('gibbon',4,1,'Where might a gibbon be seen?','in a forest canopy in Southeast Asia','on an Arctic ice floe','inside a glass kiln','in a forest canopy in Southeast Asia','长臂猿生活于亚洲森林树冠层。')]});
D('gibe',{etymology:E('Gibe is recorded in English from the sixteenth century for a taunt; its deeper origin is uncertain. It can be a verb meaning to mock, a noun meaning a mocking remark, or a verb meaning to agree or match.','gibe'),contexts:[C('gibe.s3','事实核对','His explanation did not gibe with the timestamped footage, which showed the vehicle arriving twenty minutes earlier than he claimed.','他的解释与带时间戳的录像不符；录像显示车辆比他所说的早二十分钟到达。','His explanation did not gibe with the timestamped footage / which showed the vehicle arriving / twenty minutes earlier / than he claimed.','gibe with 表示与某事一致或相符。','解释和录像的时间不一致，体现 s3。')],mistakes:[M('Her account did not gibe with the records, because it matched every date and detail exactly.','Her account did not conflict with the records, because it matched every date and detail exactly.','完全吻合不能说 did not gibe with；此处 gibe 指一致。')],quiz:[Q('gibe',1,1,'To gibe at someone is to?','mock them with an unkind remark','offer sincere praise','measure their height','mock them with an unkind remark','s1 指嘲笑、讥讽。'),Q('gibe',2,2,'A gibe is?','a mocking remark','a glass coating','a medical treatment','a mocking remark','s2 是讥讽的话。'),Q('gibe',3,3,'If two accounts gibe, they?','agree or match','contradict each other','are written in German','agree or match','s3 表示一致、相符。'),Q('gibe',4,3,'Choose the standard construction.','The figures gibe with the report.','The figures gibe againstly report.','The figures are gibe to report.','The figures gibe with the report.','表示相符时常用 gibe with。','collocation')]});
D('gifted',{etymology:E('Gifted is formed from gift plus -ed. Gift comes from Old Norse gift “a gift,” and the adjective describes someone possessing exceptional natural ability.','gifted'),contexts:[C('gifted.s1','音乐教育','The gifted violinist learned the concerto quickly, but her teacher still emphasized patient practice and careful listening.','这位有天赋的小提琴手很快学会了协奏曲，但老师仍强调耐心练习和认真聆听。','The gifted violinist learned the concerto quickly / but her teacher still emphasized / patient practice / and careful listening.','gifted 修饰 violinist，表示具有很高的天赋。','快速掌握复杂曲目体现自然才能，但仍需练习。')],mistakes:[M('The gifted student had no natural ability in music and could not recognize a single note.','The untrained student had not yet developed musical ability or note recognition.','完全没有音乐能力不符合 gifted 的天赋义。')],quiz:[Q('gifted',1,1,'A gifted musician has?','high natural talent','no ability to learn music','a musical instrument as a present only','high natural talent','gifted 指天赋很高。'),Q('gifted',2,1,'A gifted child may learn a skill?','with unusual ease or ability','only after losing all interest','without ever receiving instruction or practice','with unusual ease or ability','天赋可使学习某项技能较快。'),Q('gifted',3,1,'Which phrase is natural?','a gifted artist','a giftful artistly','an artist gifted of music','a gifted artist','gifted 可直接修饰职业名词。'),Q('gifted',4,1,'Gifted is formed from gift plus?','-ed','-ness','-ify','-ed','gifted 由 gift 加 -ed 构成。','word-formation')]});
D('gigantic',{etymology:E('Gigantic is formed from giant plus -ic; giant came through French from Latin gigas, from Greek gigas. It means extremely large or, figuratively, like a giant in scale.','gigantic'),contexts:[C('gigantic.s1','工程规模','The team moved a gigantic turbine into the new hall, using a crane because the machine was wider than the entrance.','团队把一台巨大的涡轮机运进新大厅，由于机器比入口还宽，只能使用起重机。','The team moved a gigantic turbine into the new hall / using a crane / because the machine was wider / than the entrance.','gigantic 修饰 turbine，表示体积极大。','机器尺寸超过入口，需要起重机移动，体现巨大义。')],mistakes:[M('The gigantic turbine fit in a matchbox and weighed less than a paper clip.','The tiny turbine fit in a matchbox and weighed less than a paper clip.','火柴盒大小、极轻与 gigantic 的巨大含义矛盾。')],quiz:[Q('gigantic',1,1,'A gigantic building is?','extremely large','smaller than a coin','made only of paper','extremely large','gigantic 表示极大的。'),Q('gigantic',2,2,'A gigantic achievement may be?','like a giant in importance or scale','physically tiny and unimportant','a kind of fish','like a giant in importance or scale','s2 可比喻规模或重要性巨大。'),Q('gigantic',3,1,'Which object is gigantic?','a dam stretching across a broad valley','a grain of sand','a button on a shirt','a dam stretching across a broad valley','横跨山谷的大坝体积庞大。'),Q('gigantic',4,1,'Gigantic is closest in meaning to?','enormous','minute','ordinary','enormous','enormous 同样表示巨大。')]});
D('gigot',{etymology:E('Gigot is borrowed from French gigot, “leg of mutton,” a culinary term for a sheep’s hind leg prepared as food.','gigot'),contexts:[C('gigot.s1','菜单用语','The restaurant served roast gigot with potatoes and herbs, carving the tender leg of lamb at the table.','餐厅供应配土豆和香草的烤羊腿，并在桌边切开鲜嫩的羊后腿肉。','The restaurant served roast gigot with potatoes and herbs / carving the tender leg of lamb / at the table.','gigot 是烹饪用语，指羊腿（尤指羊后腿）。','烤羊腿作为主菜上桌，符合义项。')],mistakes:[M('The menu described a gigot as a vegetarian dessert made from apples and cream.','The menu described a gigot as a roasted leg of lamb served with vegetables.','只由苹果和奶油做成的甜点不是羊腿菜肴。')],quiz:[Q('gigot',1,1,'A roast gigot is a dish made from?','a leg of sheep or lamb','a type of mushroom gill','a glass container','a leg of sheep or lamb','gigot 指羊腿肉。'),Q('gigot',2,1,'Which menu description fits gigot?','roasted lamb leg with herbs','cold fruit sorbet','fried cotton seeds','roasted lamb leg with herbs','烤羊后腿配香草符合菜名。'),Q('gigot',3,1,'Gigot is borrowed from which language?','French','German','Icelandic','French','gigot 是法语借词。'),Q('gigot',4,1,'A chef carving gigot is carving?','a leg of lamb','a glass panel','a geothermal pipe','a leg of lamb','gigot 通常指作为食物的羊腿。')]});
D('gilding',{etymology:E('Gilding is formed from gild plus -ing; gild comes from Old English gyldan “to cover with gold.” It can mean a gold or gold-coloured surface layer, or a figurative decorative improvement.','gilding'),contexts:[C('gilding.s2','修辞批评','The biographer called the invented anecdotes gilding, added to make the politician’s record look finer than the documents supported.','传记作者把编造的逸闻称为虚饰，它们被添加进来，让政治人物的履历显得比档案证据更光彩。','The biographer called the invented anecdotes gilding / added to make the politician’s record look finer / than the documents supported.','gilding 在此是比喻名词，指让事实显得更漂亮的虚饰。','编造轶事美化履历，符合 s2。')],mistakes:[M('The biography’s gilding consisted of verified records presented accurately without embellishment.','The biography’s accurate account used verified records without gilding or embellishment.','只按证据准确呈现、不加美化，不构成虚饰。')],quiz:[Q('gilding',1,1,'Gilding on a frame is?','a thin gold or gold-coloured layer','a deep crack in wood','a kind of freshwater fish','a thin gold or gold-coloured layer','s1 指表面镀金层。'),Q('gilding',2,2,'Figurative gilding in a biography means?','embellishment that makes events seem finer','a verified list of plain facts','a goldsmith’s hammer','embellishment that makes events seem finer','s2 指美化事实的虚饰。'),Q('gilding',3,1,'A restorer applies gilding to?','cover a surface with gold leaf','remove all paint and wood','freeze a glass vessel','cover a surface with gold leaf','金箔覆盖属于镀金工艺。'),Q('gilding',4,2,'The phrase “gilding the lily” suggests?','adding unnecessary embellishment','removing every decoration','planting flowers in winter','adding unnecessary embellishment','该比喻指出过度、无必要的修饰。')]});
D('gill',{etymology:E('Gill for a fish’s breathing organ is an old Germanic word, recorded in Old Norse and related English forms; the name for mushroom plates is a separate visual extension. The verb can mean catch fish in a net by their gills.','gill'),contexts:[C('gill.s2','蘑菇鉴别','The mycologist turned the mushroom over and counted the fine gills beneath its cap before identifying the species.','真菌学家把蘑菇翻过来，数了数菌盖下的细菌褶，然后辨认物种。','The mycologist turned the mushroom over / and counted the fine gills beneath its cap / before identifying the species.','gill 在此指菌盖下方薄片状的菌褶。','菌褶位于蘑菇伞盖下，是鉴定特征。')],mistakes:[M('The mushroom’s gills were the broad leaves growing above its cap.','The mushroom’s gills were the thin plates beneath its cap.','菌褶位于菌盖下面，不是上方的叶片。')],quiz:[Q('gill',1,1,'A fish uses its gills to?','breathe underwater','produce feathers','make glass','breathe underwater','s1 指鱼类用于水中呼吸的器官。'),Q('gill',2,2,'Mushroom gills are found?','under the cap','inside a fish’s mouth','on a flagpole','under the cap','s2 指蘑菇伞盖下的薄片。'),Q('gill',3,3,'To gill a fish with a net is to?','catch it so the mesh holds at its gills','paint its scales gold','teach it to breathe air','catch it so the mesh holds at its gills','s3 指用刺网从鳃处挂住并捕鱼。'),Q('gill',4,1,'Which organ lets a fish extract oxygen from water?','gills','lungs only','fins','gills','鱼用鳃从水中获取氧气。')]});

D('gimmick',{etymology:E('Gimmick is an American English word recorded in the early twentieth century; its earlier origin is uncertain. It names a novel trick or device used to attract attention, especially in selling or entertainment.','gimmick'),contexts:[C('gimmick.s1','产品宣传','The phone maker’s free hologram sleeve was a gimmick that drew shoppers to the launch table but did nothing to improve the phone.','手机厂商赠送的全息外壳只是个吸引人的噱头，把顾客引到发布台前，却没有改善手机性能。','The phone maker’s free hologram sleeve was a gimmick / that drew shoppers to the launch table / but did nothing / to improve the phone.','gimmick 在此指为招徕注意而设计的新奇花招。','配件仅吸引顾客，没有实际改善功能，符合“噱头”义。')],mistakes:[M('The company called its elaborate sales trick a gimmick, although it was an ordinary feature with no attempt to attract attention.','The company called its elaborate attention-getting sales trick a gimmick.','无意吸引注意的普通功能不构成这里所说的营销噱头。')],quiz:[Q('gimmick',1,1,'A sales gimmick is mainly designed to?','attract attention with a novel trick','repair a product’s internal damage','record a customer’s address','attract attention with a novel trick','gimmick 常指吸引注意的花招。'),Q('gimmick',2,1,'Which item is most likely a gimmick?','a flashy feature added only to make a product seem exciting','a safety test that measures battery temperature','a plain instruction manual','a flashy feature added only to make a product seem exciting','只为制造新奇感而添加的功能符合噱头义。'),Q('gimmick',3,2,'In the verb “to gimmick a device,” one would?','fit it with a trick or hidden device','remove all of its controls','translate its instruction book','fit it with a trick or hidden device','s2 是给某物装上机关或噱头。'),Q('gimmick',4,1,'Calling a promotion a gimmick often suggests it is?','attention-getting but not very substantial','a carefully tested medical treatment','a standard measurement unit','attention-getting but not very substantial','语境中的 gimmick 往往是表面吸睛、实质有限的招数。')]});
D('gin',{etymology:E('Gin is shortened from geneva, an English form of Dutch jenever, ultimately related to juniper. The drink is flavoured with juniper berries; the cotton-processing sense is a separate use of gin as a machine name.','gin'),contexts:[C('gin.s1','饮品菜单','The bartender poured gin over ice and added tonic water, a strip of lime peel, and a sprig of rosemary.','调酒师把杜松子酒倒在冰块上，加入汤力水、青柠皮和一枝迷迭香。','The bartender poured gin over ice / and added tonic water / a strip of lime peel / and a sprig of rosemary.','gin 在此是以杜松子调味的烈性酒。','调酒中与汤力水、青柠搭配的 gin 指酒类。')],mistakes:[M('The farm worker used gin as a clear juniper-flavoured drink to separate cotton fibres from their seeds.','The farm worker used a cotton gin to separate cotton fibres from their seeds.','分离棉籽需用轧棉机；酒类义不能完成这个动作。')],quiz:[Q('gin',1,1,'The flavour traditionally associated with gin comes from?','juniper berries','cocoa beans','roasted cotton seeds','juniper berries','杜松子是 gin 的标志性风味来源。'),Q('gin',2,1,'A gin and tonic contains gin as?','an alcoholic drink','a cotton-processing machine','a type of fabric','an alcoholic drink','菜单上的 gin 指杜松子酒。'),Q('gin',3,2,'A cotton gin is used to?','separate fibres from cotton seeds','press grapes into wine','spin wool into cloth','separate fibres from cotton seeds','s2 指轧棉机或轧棉动作。'),Q('gin',4,1,'Which description fits gin in a cocktail recipe?','a clear spirit flavoured with juniper','a sweet paste made of cotton','a chilled fruit juice','a clear spirit flavoured with juniper','gin 是常用于鸡尾酒的杜松子酒。')]});
D('ginger',{etymology:E('Ginger came into English through Old English from Latin zingiberi and Greek zingiberis, ultimately from an Indic source. The root is the aromatic rhizome; the verb can mean add ginger or make something livelier.','ginger'),contexts:[C('ginger.s1','烘焙调味','She grated fresh ginger into the pear cake batter, then added a little cinnamon before folding in the fruit.','她把新鲜姜末擦入梨子蛋糕面糊，再加少许肉桂，然后拌入水果。','She grated fresh ginger into the pear cake batter / then added a little cinnamon / before folding in the fruit.','ginger 在此指姜这种辛香根茎。','姜末作为食材加入蛋糕面糊，符合名词义。')],mistakes:[M('He added ginger to the cake to make it taste less spicy, then removed all the mild ingredients.','He left the ginger out of the cake to make it taste less spicy.','姜味辛辣，加入姜通常会增添而非减少辛辣味。')],quiz:[Q('ginger',1,1,'Fresh ginger is the edible part of a?','tropical plant’s aromatic rhizome','tree that produces cocoa beans','seaweed used for glass','tropical plant’s aromatic rhizome','ginger 是姜科植物有辛味的根茎。'),Q('ginger',2,2,'To ginger up a dull presentation is to?','make it more lively','make it colder','remove its spoken words','make it more lively','动词 ginger up 可表示使更有生气。'),Q('ginger',3,1,'Which recipe probably calls for ginger as an ingredient?','a spiced pear cake','a plain glass window','a cotton field map','a spiced pear cake','姜常用于烘焙和调味。'),Q('ginger',4,2,'In “ginger the sauce,” the verb most likely means?','add ginger to it','freeze it solid','serve it without flavour','add ginger to it','ginger 作动词也可表示加姜调味。')]});
D('gingham',{etymology:E('Gingham entered English from French guingan, a word for a striped cotton fabric, ultimately associated with Malay genggang “striped.” Today gingham commonly has a checked pattern.','gingham'),contexts:[C('gingham.s1','服装面料','The picnic dress was sewn from lightweight blue-and-white gingham, whose small checks stayed crisp after washing.','这条野餐连衣裙用轻薄的蓝白方格棉布缝成，洗后小格纹依然清晰。','The picnic dress was sewn from lightweight blue-and-white gingham / whose small checks / stayed crisp after washing.','gingham 指常见方格或条纹图案的轻质棉布。','蓝白小格纹棉布是典型 gingham。')],mistakes:[M('The tailor chose gingham, a heavy transparent sheet of steel, for the summer shirt.','The tailor chose gingham, a lightweight checked cotton cloth, for the summer shirt.','gingham 是棉织物，不是钢材。')],quiz:[Q('gingham',1,1,'Gingham is a kind of?','light cotton fabric, often checked','heavy metal mesh','transparent stone','light cotton fabric, often checked','gingham 常指轻质格纹棉布。'),Q('gingham',2,1,'A gingham tablecloth is likely to show?','checks or stripes','a solid layer of glass','a map of mountain glaciers','checks or stripes','方格或条纹是 gingham 的常见图案。'),Q('gingham',3,1,'Which item could naturally be made of gingham?','a summer shirt','a steel bridge girder','a fish’s gill','a summer shirt','轻质棉布适合制作衬衫。'),Q('gingham',4,1,'The word gingham describes primarily?','a patterned cotton textile','a juniper-flavoured spirit','a tall African ape','a patterned cotton textile','gingham 是面料名称。')]});
D('giraffe',{etymology:E('Giraffe came through Italian giraffa and Arabic zarāfa, with a likely African origin whose deeper history is uncertain. It names the very tall African mammal with a long neck and spotted coat.','giraffe'),contexts:[C('giraffe.s1','野生动物园','A giraffe stretched its long tongue around the thorny branch and pulled down leaves that the antelopes could not reach.','一只长颈鹿伸出长舌绕住带刺的树枝，拉下羚羊够不到的树叶。','A giraffe stretched its long tongue / around the thorny branch / and pulled down leaves / that the antelopes could not reach.','giraffe 指长颈鹿；长颈和取食高处树叶是明显特征。','伸舌取食高处树叶符合长颈鹿习性。')],mistakes:[M('The giraffe reached the ground leaves with its short neck, while the tall-necked animal watched from above.','The giraffe reached high leaves with its long neck.','长颈鹿以长颈著称，句中短颈设定与词义相冲突。')],quiz:[Q('giraffe',1,1,'A giraffe is recognized especially by its?','long neck and spotted coat','flat bill and webbed feet','transparent wings','long neck and spotted coat','长颈与斑点是长颈鹿的典型特征。'),Q('giraffe',2,1,'What does a giraffe commonly eat from trees?','leaves high on branches','roots beneath frozen soil','fish caught in a net','leaves high on branches','长颈鹿会取食高枝上的叶子。'),Q('giraffe',3,1,'Where does a giraffe live naturally?','in parts of Africa','in Arctic ice caves','only in European rivers','in parts of Africa','长颈鹿原生分布于非洲。'),Q('giraffe',4,1,'Which animal is the tallest living land mammal?','the giraffe','the gorilla','the gosling','the giraffe','长颈鹿是现存最高的陆生动物。')]});
D('girder',{etymology:E('Girder is formed from gird plus -er, originally referring to a principal supporting beam; gird itself is related to Old English gyrdan “to encircle or bind.”','girder'),contexts:[C('girder.s1','桥梁工程','Engineers inspected the steel girder beneath the bridge deck for cracks before reopening the lane to heavy trucks.','工程师在允许重型卡车通行前，检查了桥面下方的钢制大梁是否有裂缝。','Engineers inspected the steel girder beneath the bridge deck / for cracks / before reopening the lane / to heavy trucks.','girder 指承载结构荷载的粗大梁。','桥面下的钢梁承重，符合 girder 的工程义。')],mistakes:[M('The steel girder was a soft curtain hung above the bridge, carrying no structural load.','The steel girder was a heavy beam beneath the bridge, carrying structural load.','girder 是承重梁，不是窗帘。')],quiz:[Q('girder',1,1,'A bridge girder primarily?','carries structural loads','filters drinking water','covers a person’s waist','carries structural loads','girder 是承重用的大梁。'),Q('girder',2,1,'Which material is commonly used for a large girder?','steel','gingham cotton','gouache paint','steel','桥梁大梁常为钢制。'),Q('girder',3,1,'A cracked girder on a bridge should concern?','structural engineers','a pastry chef','a mushroom grower','structural engineers','梁体裂缝关系桥梁结构安全。'),Q('girder',4,1,'A girder is best described as?','a heavy supporting beam','a small decorative button','a thin sheet of paper','a heavy supporting beam','girder 指沉重的支撑梁。')]});
D('girdle',{etymology:E('Girdle is from Old English gyrdel “belt,” related to gird “to encircle or bind.” As a verb it can mean surround a place like a belt.','girdle'),contexts:[C('girdle.s2','地理描写','A narrow belt of woodland girdles the lake, separating the open fields from the water on every side.','一条狭长林带环绕着湖泊，把开阔田野与四周水面隔开。','A narrow belt of woodland girdles the lake / separating the open fields / from the water / on every side.','girdles 在此是动词，表示像腰带一样环绕。','林带围绕湖岸一周，符合 s2。')],mistakes:[M('A thin belt of trees girdled the lake only by standing in a distant line that never surrounded it.','A thin belt of trees bordered the lake without girdling it.','仅沿一侧远远成线、不形成环绕，不宜称 girdle。')],quiz:[Q('girdle',1,1,'A girdle worn around the body is?','a belt or band','a glassmaking furnace','a fish’s breathing organ','a belt or band','s1 指腰间的带子。'),Q('girdle',2,2,'A forest that girdles a lake?','surrounds it like a belt','dries up its water','floats on its surface','surrounds it like a belt','动词 s2 指环绕某地。'),Q('girdle',3,1,'Which sentence uses girdle as a verb?','A wall girdles the old town.','She bought a girdle at the shop.','The glass is girdle.','A wall girdles the old town.','girdles 作谓语时表示围住。'),Q('girdle',4,2,'If hills girdle a valley, they?','form a ring around it','cut it into tiny pieces','turn it into a glacier','form a ring around it','山丘环绕山谷，符合动词义。')]});
D('glacial',{etymology:E('Glacial is from Latin glacialis, from glacies “ice,” with the suffix -al. It can refer to glaciers and ice ages, extreme cold, or very slow movement.','glacial'),contexts:[C('glacial.s3','审批进度','After the application entered its fourth review queue, the promised two-week decision stretched at a glacial pace into its seventh month.','申请进入第四个审核队列后，原定两周内作出的决定以冰川般的速度拖到了第七个月。','After the application entered its fourth review queue / the promised two-week decision / stretched at a glacial pace / into its seventh month.','glacial 修饰 pace，作比喻表示极其缓慢。','审核耗时远超承诺，符合 s3 的“缓慢”义。')],mistakes:[M('The queue moved at a glacial pace, clearing all four hundred cases in a single minute.','The queue moved at a rapid pace, clearing all four hundred cases in a single minute.','一分钟处理四百件表现迅速，与 glacial pace 的极慢义矛盾。')],quiz:[Q('glacial',1,1,'A glacial valley is one?','formed or shaped by glacier ice','heated by a desert sun','built from cotton cloth','formed or shaped by glacier ice','s1 指与冰川相关的地貌。'),Q('glacial',2,2,'A glacial stare may feel?','extremely cold and unfriendly','warm and welcoming','brightly coloured','extremely cold and unfriendly','s2 可比喻冷漠如冰。'),Q('glacial',3,3,'A response arriving after months may be called glacial because it is?','extremely slow','made of ice','angry and loud','extremely slow','s3 表示像冰川移动般缓慢。'),Q('glacial',4,1,'Which science studies glacial deposits?','glaciology','gingham weaving','glassblowing','glaciology','冰川沉积属于冰川学研究内容。')]});
D('glaciate',{etymology:E('Glaciate is formed from Latin glacies “ice” with the verb suffix -ate. It means subject land to glacier ice, including the erosion and deposition caused by moving ice.','glaciate'),contexts:[C('glaciate.s1','地貌演变','During the ice age, advancing ice sheets glaciate the upland, carving broad valleys and leaving ridges of till when they retreat.','冰期中，推进的冰盖使高地遭受冰川作用，刻出宽谷，并在退缩时留下冰碛脊。','During the ice age / advancing ice sheets glaciate the upland / carving broad valleys / and leaving ridges of till when they retreat.','glaciate 是动词，表示冰川覆盖并改造地表。','冰蚀地貌与冰碛沉积都是冰川作用的结果。')],mistakes:[M('The valley was glaciated by dry desert winds that deposited no ice or glacial sediment.','The valley was shaped by desert winds that deposited no ice or glacial sediment.','干燥沙漠风没有冰川覆盖或冰川沉积，不能说使地表 glaciate。')],quiz:[Q('glaciate',1,1,'To glaciate a landscape is to?','subject it to glacier ice and its effects','cover it only with dry sand','heat it until all rock melts','subject it to glacier ice and its effects','glaciate 指冰川覆盖及其地貌作用。'),Q('glaciate',2,1,'A glacier may glaciate a valley by?','eroding rock and depositing till','painting the rocks with varnish','draining all rivers by evaporation','eroding rock and depositing till','冰川会侵蚀地表并堆积冰碛物。'),Q('glaciate',3,1,'Which force can glaciate a mountain region?','an advancing ice sheet','a cotton gin','a summer breeze only','an advancing ice sheet','推进的冰盖可使山区发生冰川作用。'),Q('glaciate',4,1,'Glaciate is a verb related to?','ice and glaciers','the production of gin','the weaving of cloth','ice and glaciers','词义与冰川有关。')]});
D('glaciation',{etymology:E('Glaciation is formed from glaciate plus -ion. It names the covering of land by glaciers and the associated erosion and deposition, or a period in which these occur.','glaciation'),contexts:[C('glaciation.s1','地质调查','The geologist identified signs of past glaciation in the polished bedrock, U-shaped valleys, and unsorted deposits left beyond the old ice margin.','地质学家在磨光的基岩、U形山谷以及古冰缘外的混杂沉积物中辨认出昔日冰川作用的迹象。','The geologist identified signs of past glaciation / in the polished bedrock / U-shaped valleys / and unsorted deposits left beyond the old ice margin.','glaciation 指冰川覆盖及其侵蚀、沉积作用。','磨光基岩、U形谷和冰碛沉积都表明曾发生冰川作用。')],mistakes:[M('The geologist called the dune field glaciation even though no ice, glacier erosion, or glacial deposits were involved.','The geologist called the dune field aeolian landforms because wind shaped it without ice.','风成沙丘由风形成；没有冰川作用就不是 glaciation。')],quiz:[Q('glaciation',1,1,'Glaciation refers to?','land being covered and shaped by glaciers','cotton fibres being separated from seeds','paint being mixed with water','land being covered and shaped by glaciers','glaciation 是冰川覆盖及改造地表的过程。'),Q('glaciation',2,1,'A U-shaped valley may be evidence of?','past glaciation','a cotton harvest','gesso under a painting','past glaciation','U形谷常由冰川侵蚀形成。'),Q('glaciation',3,1,'Which deposit is associated with glaciation?','unsorted till left by ice','a neat row of glass cups','juniper berries in a bottle','unsorted till left by ice','冰川搬运和堆积的混杂物称冰碛物。'),Q('glaciation',4,1,'The suffix -ation in glaciation helps form a noun for?','a process or state','a person who paints','a small animal','a process or state','-ation 常构成过程或状态名词。','word-formation')]});
D('glamorous',{etymology:E('Glamorous is formed from glamour plus -ous. Glamour was originally a Scots form associated with magic or enchantment and later came to mean an attractive, exciting quality.','glamorous'),contexts:[C('glamorous.s2','职业宣传','The brochure showed glamorous premieres and red carpets but omitted the long unpaid rehearsals behind the advertised acting career.','宣传册展示了光鲜的首映礼和红毯，却略去了宣传中那份演艺职业背后漫长且无薪的排练。','The brochure showed glamorous premieres and red carpets / but omitted the long unpaid rehearsals / behind the advertised acting career.','glamorous 在这里指表面看起来充满名望或刺激、因而诱人的。','宣传突出光鲜场面而掩盖繁重工作，符合 s2。')],mistakes:[M('The brochure described the glamorous career as ordinary and dull precisely because fame and excitement were guaranteed.','The brochure made the career seem glamorous by emphasizing fame and excitement.','保证名望和刺激会让职业显得光鲜诱人，而不是平淡无奇。')],quiz:[Q('glamorous',1,1,'A glamorous gown is?','attractive in a special, exciting way','made from glacier ice','used to filter cotton seeds','attractive in a special, exciting way','s1 表示有魅力、迷人。'),Q('glamorous',2,2,'A job may seem glamorous when it promises?','fame and excitement','only routine paperwork with no public attention','a lower temperature','fame and excitement','s2 指因名利或刺激而显得诱人的工作。'),Q('glamorous',3,1,'Which scene sounds glamorous?','a sparkling premiere with photographers','a broken pipe in an empty basement','a plain unlabeled storage box','a sparkling premiere with photographers','闪耀的首映礼具有迷人、光鲜的外观。'),Q('glamorous',4,2,'A glamorous image can hide?','the routine work behind the excitement','the fact that glass is transparent','the spelling of a country name','the routine work behind the excitement','表面光鲜可能掩盖日常辛劳。')]});
D('glandular',{etymology:E('Glandular is formed from gland plus -ular, ultimately related to Latin glandula “small gland.” It describes something belonging to or produced by a gland.','glandular'),contexts:[C('glandular.s1','生理学','The clinician noted glandular swelling beneath the jaw and ordered tests to determine whether an infection had affected the lymph nodes.','临床医生注意到下颌下方腺体肿胀，于是安排检查以判断感染是否影响了淋巴结。','The clinician noted glandular swelling beneath the jaw / and ordered tests / to determine whether an infection / had affected the lymph nodes.','glandular 修饰 swelling，表示与腺体有关。','淋巴结属于淋巴系统的腺体组织，肿胀符合腺体义。')],mistakes:[M('The glandular tissue had no glands or secretory cells and consisted only of polished glass.','The glandular tissue contained glands or secretory cells rather than polished glass.','glandular 描述腺体或其分泌功能相关组织。')],quiz:[Q('glandular',1,1,'Glandular tissue is connected with?','glands that secrete substances','steel beams that carry bridges','cotton cloth patterns','glands that secrete substances','glandular 指与腺体及分泌有关。'),Q('glandular',2,1,'A glandular disorder may affect?','a hormone-producing gland','a glassmaking furnace only','a mountain glacier only','a hormone-producing gland','激素由内分泌腺产生。'),Q('glandular',3,1,'Which phrase uses glandular correctly?','glandular cells release a secretion','glandular cotton was woven into checks','a glandular girder carried the bridge','glandular cells release a secretion','腺细胞分泌物质，搭配自然。'),Q('glandular',4,1,'The suffix -ular in glandular helps form an adjective meaning?','related to a gland','made entirely of sugar','moving very slowly','related to a gland','该后缀参与构成表示“与……有关”的形容词。','word-formation')]});
D('glaring',{etymology:E('Glaring is the present participle of glare, from a Germanic word associated with shining brightly or staring fiercely. It can describe harsh light, an obvious error, or an angry stare.','glaring'),contexts:[C('glaring.s2','校样审阅','The reviewer caught a glaring date error on the first page: the report claimed the 2025 survey had finished in 2022.','审阅者在第一页就发现一处明显的日期错误：报告称2025年的调查于2022年完成。','The reviewer caught a glaring date error on the first page / the report claimed / the 2025 survey / had finished in 2022.','glaring 修饰 date error，表示显眼到无法忽视。','调查完成时间早于调查年份，错误非常明显。')],mistakes:[M('The glaring typo was impossible to notice because it was hidden in tiny white letters on a white page.','The barely visible typo was difficult to notice because it was hidden in tiny white letters on a white page.','白字藏在白页上难以察觉，不能称为 glaring error。')],quiz:[Q('glaring',1,1,'Glaring sunlight is?','so bright that it hurts the eyes','too faint to see','a type of cotton fabric','so bright that it hurts the eyes','s1 描述刺眼的强光。'),Q('glaring',2,2,'A glaring mistake is one that is?','obvious and hard to ignore','correct in every detail','hidden from all readers','obvious and hard to ignore','s2 指非常明显的错误。'),Q('glaring',3,3,'A glaring look usually shows?','an angry, fierce stare','a sleepy smile','careful reading','an angry, fierce stare','s3 是怒目而视。'),Q('glaring',4,2,'Which is a glaring contradiction?','a report dated 2025 says the event ended in 2022','a page uses one consistent date throughout','a book lists its author on the cover','a report dated 2025 says the event ended in 2022','时间前后矛盾明显，属于 glaring contradiction。')]});
D('glasslike',{etymology:E('Glasslike is a transparent compound of glass and -like, meaning resembling glass in appearance or surface qualities.','glasslike'),contexts:[C('glasslike.s1','冰面观察','At dawn the sheltered pond had a glasslike surface, so smooth and clear that the reflected reeds looked like a second stand of plants.','黎明时避风池塘的表面像玻璃一样平滑清澈，映出的芦苇看起来仿佛另一片植物。','At dawn the sheltered pond had a glasslike surface / so smooth and clear / that the reflected reeds looked like a second stand of plants.','glasslike 描述表面似玻璃般平滑、发亮或清澈。','平静、清澈的水面呈现玻璃般外观。')],mistakes:[M('The opaque rough surface was glasslike, although light could not pass through it and it felt coarse.','The opaque rough surface was unlike glass, although it was durable.','完全不透明且粗糙的表面不具备这里所说的玻璃般透明光滑特征。')],quiz:[Q('glasslike',1,1,'A glasslike surface is likely to be?','smooth, shiny, or clear like glass','soft and furry','made of cotton checks','smooth, shiny, or clear like glass','-like 表示“像……一样”。'),Q('glasslike',2,1,'Which surface could look glasslike?','a still, clear pond at dawn','a shaggy wool blanket','a rough, opaque sack','a still, clear pond at dawn','平静清澈的水面会像玻璃。'),Q('glasslike',3,1,'Does glasslike always mean an object is literally made of glass?','No; it may only resemble glass.','Yes; it must be pure glass.','Only when it is made of cotton.','No; it may only resemble glass.','-like 表示相似，并非材料成分。'),Q('glasslike',4,1,'The suffix -like in glasslike means?','having a resemblance to','removing the surface of','measuring the weight of','having a resemblance to','glasslike 是“像玻璃的”复合形容词。','word-formation')]});
D('glassmaker',{etymology:E('Glassmaker combines glass with maker, from make plus the agent suffix -er. It names a person or business whose craft is producing glass or glass objects.','glassmaker'),contexts:[C('glassmaker.s1','工艺作坊','The glassmaker heated a silica mixture in the furnace, then shaped the glowing material into a small bottle with a blowpipe.','玻璃工匠在炉中加热二氧化硅混合料，再用吹管把发光的熔融材料塑成小瓶。','The glassmaker heated a silica mixture in the furnace / then shaped the glowing material / into a small bottle / with a blowpipe.','glassmaker 指以制造玻璃为手艺或营生的人。','加热原料并吹制玻璃器物是玻璃工匠的工作。')],mistakes:[M('The glassmaker shaped the bottle by weaving gingham cotton, without melting or handling any glass.','The textile maker wove the gingham cotton, while a glassmaker shaped glass in a furnace.','织造棉布属于纺织工艺，不是玻璃制造。')],quiz:[Q('glassmaker',1,1,'A glassmaker works primarily with?','molten glass and glass objects','glaciers and ice sheets','juniper-flavoured spirits','molten glass and glass objects','glassmaker 是制造玻璃或玻璃器物的人。'),Q('glassmaker',2,1,'Which tool might a glassmaker use?','a blowpipe','a cotton gin','a fishing gill net','a blowpipe','吹管是玻璃吹制工具。'),Q('glassmaker',3,1,'A glassmaker’s workshop is likely to contain?','a furnace for heating glass','a field of cotton plants only','a glacier research station','a furnace for heating glass','制造玻璃需加热熔融原料。'),Q('glassmaker',4,1,'The suffix -maker identifies someone who?','makes or produces something','studies only animal behaviour','governs a country','makes or produces something','maker 表示制造者。','word-formation')]});
D('glassmaking',{etymology:E('Glassmaking combines glass with the verbal noun making, from make plus -ing. It refers to the process and industry of producing glass from raw materials.','glassmaking'),contexts:[C('glassmaking.s1','制造流程','In glassmaking, sand, soda ash, and limestone are heated until they melt into a liquid that can be shaped and cooled.','在玻璃制造中，沙子、纯碱和石灰石被加热至熔化成液体，再经塑形和冷却。','In glassmaking / sand, soda ash, and limestone are heated / until they melt into a liquid / that can be shaped and cooled.','glassmaking 指从原料生产玻璃的过程或行业。','原料加热、熔化、塑形与冷却构成制造流程。')],mistakes:[M('Glassmaking is the process of separating cotton fibres from seeds, with no glass or furnace involved.','Cotton ginning is the process of separating cotton fibres from seeds.','分离棉纤维属于轧棉；glassmaking 是玻璃制造。')],quiz:[Q('glassmaking',1,1,'Glassmaking begins with?','raw materials heated and melted','a fish caught by its gills','cloth woven from checked cotton','raw materials heated and melted','玻璃制造通常从加热原料开始。'),Q('glassmaking',2,1,'Which process belongs to glassmaking?','shaping molten glass as it cools','growing a giraffe’s spotted coat','adding gin to a cocktail','shaping molten glass as it cools','熔融玻璃的塑形和冷却属于制造工艺。'),Q('glassmaking',3,1,'Glassmaking can refer to?','the craft and industry of producing glass','the governance of a state','the study of plant sugars only','the craft and industry of producing glass','该词兼指工艺与行业。'),Q('glassmaking',4,1,'The compound glassmaking names a process of?','making glass','making cotton gin','making glacier ice','making glass','词素组合表达制造玻璃的过程。','word-formation')]});
D('glassware',{etymology:E('Glassware combines glass with ware, an old word for manufactured articles or goods. It names drinking glasses, bowls, and other objects made of glass.','glassware'),contexts:[C('glassware.s1','实验室整理','After washing the glassware, the technician checked each beaker for chips and returned the intact pieces to the labeled cabinet.','洗完玻璃器皿后，技术员检查每只烧杯是否有缺口，并把完好的器皿放回贴有标签的柜子。','After washing the glassware / the technician checked each beaker for chips / and returned the intact pieces / to the labeled cabinet.','glassware 是玻璃制成器皿的总称。','烧杯属于实验室玻璃器皿。')],mistakes:[M('The glassware cupboard held only wool blankets and cotton shirts, with no glass objects inside.','The clothing cupboard held wool blankets and cotton shirts, while the glassware cupboard held glass vessels.','纺织品不属于 glassware。')],quiz:[Q('glassware',1,1,'Which item is glassware?','a drinking tumbler','a gingham tablecloth','a steel girder','a drinking tumbler','玻璃杯属于 glassware。'),Q('glassware',2,1,'A laboratory may store glassware such as?','beakers and flasks','cotton gin parts only','wooden tree leaves','beakers and flasks','烧杯和玻璃瓶是常见实验室玻璃器皿。'),Q('glassware',3,1,'The word glassware refers to?','articles made of glass','a person who governs a state','a kind of glacier','articles made of glass','ware 表示制成品或器物。'),Q('glassware',4,1,'If a cup is chipped, a lab worker may remove it from the glassware shelf because it is?','damaged and unsafe to use','made of checked cotton','a type of gin','damaged and unsafe to use','玻璃器皿有缺口会带来安全风险。')]});
D('glasswork',{etymology:E('Glasswork combines glass and work; it can mean objects made of glass or the craft of shaping and decorating glass.','glasswork'),contexts:[C('glasswork.s1','艺术工坊','The museum displayed the glassworker’s glasswork beside the furnace tools, including a blue vessel and a panel with delicate etched lines.','博物馆把玻璃工匠的玻璃作品与炉具并列展出，其中有一只蓝色器皿和一块带精细蚀刻线条的面板。','The museum displayed the glassworker’s glasswork / beside the furnace tools / including a blue vessel / and a panel with delicate etched lines.','glasswork 可指玻璃制品，也可指制作玻璃制品的工艺。','展出的器皿和蚀刻面板都是玻璃作品。')],mistakes:[M('The museum labeled a checked cotton apron as glasswork even though it contained no glass and used no glassmaking craft.','The museum labeled the checked cotton apron as textile work rather than glasswork.','棉布制品不属于玻璃制品或玻璃工艺。')],quiz:[Q('glasswork',1,1,'Glasswork may refer to?','glass objects or the craft of making them','cotton farming only','a government office','glass objects or the craft of making them','glasswork 可指玻璃作品或玻璃工艺。'),Q('glasswork',2,1,'Which display is glasswork?','a hand-blown glass vessel','a gingham shirt','a steel bridge girder','a hand-blown glass vessel','手工吹制的玻璃器物属于 glasswork。'),Q('glasswork',3,1,'A person learning glasswork might practise?','shaping molten glass','growing a cotton crop','studying a fish’s gills','shaping molten glass','塑造熔融玻璃属于玻璃工艺。'),Q('glasswork',4,1,'Glasswork is most closely connected with?','glassmaking and glass objects','glaciation and ice deposits','governmental elections','glassmaking and glass objects','该词围绕玻璃制作与制品。')]});
D('glassy',{etymology:E('Glassy is formed from glass plus -y. It describes a shiny or still surface like glass, and can also describe blank, unfocused eyes.','glassy'),contexts:[C('glassy.s2','健康观察','After the fever rose, the child’s eyes looked glassy and unfocused, so her parent called the clinic for advice.','发烧加重后，孩子的眼神显得呆滞而无法聚焦，于是家长致电诊所咨询。','After the fever rose / the child’s eyes looked glassy and unfocused / so her parent / called the clinic for advice.','glassy 在此形容目光呆滞、没有焦点。','unfocused 与 fever 描写支持目光无神的 s2。')],mistakes:[M('His glassy eyes tracked every moving object sharply and showed lively, focused attention.','His alert eyes tracked every moving object sharply and showed lively, focused attention.','目光敏锐、专注与 glassy eyes 的呆滞义相反。')],quiz:[Q('glassy',1,1,'A glassy lake is likely to have a surface that is?','smooth and still','rough and furry','deeply checked like cloth','smooth and still','s1 可描写如玻璃般平静光滑的水面。'),Q('glassy',2,2,'Glassy eyes may look?','blank and unfocused','brightly attentive','covered with cotton','blank and unfocused','s2 指目光呆滞、失焦。'),Q('glassy',3,1,'Which sentence uses glassy for a surface?','The glassy pond reflected the clouds.','Her glassy answer governed the debate.','The glassy giraffe ate leaves.','The glassy pond reflected the clouds.','平静反光的池面可以称 glassy。'),Q('glassy',4,2,'A tired patient with glassy eyes may appear?','dazed or unresponsive','cheerful and sharply focused','made of glass','dazed or unresponsive','此处描述眼神茫然，不是材质。')]});
D('glaze',{etymology:E('Glaze is related to glass and German Glas; the verb originally refers to giving a surface a glass-like finish. It can mean coat pottery, become dull-eyed, or the shiny coating itself.','glaze'),contexts:[C('glaze.s1','陶艺烧制','The potter brushed a thin blue glaze over the bowl and fired it again, leaving a glossy coating fused to the clay.','陶艺师在碗上刷了一层薄薄的蓝釉并再次烧制，留下与陶土熔合的光亮涂层。','The potter brushed a thin blue glaze over the bowl / and fired it again / leaving a glossy coating / fused to the clay.','glaze 作动词表示给陶器上釉。','蓝釉经烧制与陶土融合，符合 s1。')],mistakes:[M('The potter glazed the bowl by leaving its clay surface bare and removing every shiny coating.','The potter left the bowl unglazed by removing every shiny coating.','去掉釉层是不上釉，不能说 glaze the bowl。')],quiz:[Q('glaze',1,1,'To glaze pottery is to?','cover it with a shiny glass-like coating','wrap it in checked cotton','freeze it into a glacier','cover it with a shiny glass-like coating','s1 指给陶器上釉。'),Q('glaze',2,2,'If someone’s eyes glaze over during a lecture, they?','become dull and unfocused','turn into glass objects','shine with anger at a person','become dull and unfocused','s2 指眼神变得呆滞。'),Q('glaze',3,3,'A ceramic glaze is?','a shiny coating on pottery','a cotton-separating machine','a tall African mammal','a shiny coating on pottery','s3 是陶器表面的光亮釉层。'),Q('glaze',4,1,'A bowl is fired after glaze is applied so the coating can?','fuse to the ceramic surface','become a cotton fibre','turn into a juniper drink','fuse to the ceramic surface','烧制使釉层与陶器表面结合。')]});

D('glazed',{etymology:E('Glazed is the past participle of glaze, a verb related to glass and German Glas. It can describe pottery with a fired glass-like coating or eyes that look dull and unfocused.','glazed'),contexts:[C('glazed.s2','疲倦状态','By the final lecture slide, several students had glazed eyes and were staring past the projector without following the diagrams.','讲座放到最后一张幻灯片时，几名学生眼神呆滞，盯着投影仪却没有跟上图示内容。','By the final lecture slide / several students had glazed eyes / and were staring past the projector / without following the diagrams.','glazed 在此描写眼睛疲倦、茫然而不聚焦。','未跟上讲解、目光失焦符合 s2。')],mistakes:[M('The glazed-eyed students followed every diagram attentively and answered each question at once.','The alert students followed every diagram attentively and answered each question at once.','注意力集中、回答迅速与 glazed eyes 的茫然状态相反。')],quiz:[Q('glazed',1,1,'Glazed pottery has?','a shiny coating fused to its surface','a cotton check pattern','a coat of animal fur','a shiny coating fused to its surface','s1 指陶器上过釉或表面光亮。'),Q('glazed',2,2,'A person with glazed eyes may look?','blank and unfocused','angry and sharply attentive','covered in pottery glaze','blank and unfocused','s2 指目光呆滞。'),Q('glazed',3,1,'A ceramic bowl is glazed when it is?','coated and fired with a glass-like layer','left rough with no surface coating','woven from gingham','coated and fired with a glass-like layer','陶器上釉后烧制，形成光亮釉面。'),Q('glazed',4,2,'After hours without sleep, someone may stare with glazed eyes because they are?','tired and not focusing','made of actual glass','painted with blue glaze','tired and not focusing','疲劳会使目光显得茫然。')]});
D('glean',{etymology:E('Glean comes through Old French glener from a Late Latin verb meaning gather ears of grain. It first meant collect leftover grain and also developed the figurative sense of gathering information bit by bit.','glean'),contexts:[C('glean.s1','档案研究','From shipping logs, repair notes, and a few letters, the historian gleaned that the remote station had been abandoned before winter.','历史学家从航运日志、维修记录和几封信中一点点搜集信息，推断那座偏远站点在冬天前就被废弃了。','From shipping logs, repair notes, and a few letters / the historian gleaned / that the remote station / had been abandoned before winter.','gleaned 在此表示从零散材料中逐渐获得信息。','多个来源拼成结论，符合 s1。')],mistakes:[M('The historian gleaned the conclusion from a single complete official report without consulting fragments of evidence.','The historian read the conclusion in a complete official report.','直接读取完整报告不体现从零碎信息中慢慢搜集的 glean 方式。')],quiz:[Q('glean',1,1,'To glean information is to gather it?','bit by bit from available clues','all at once from a blank page','by burning the source documents','bit by bit from available clues','s1 是一点点搜集信息。'),Q('glean',2,2,'A farmer who gleans a field?','picks up grain left after the harvest','plants glass vessels in the soil','cuts a bridge girder','picks up grain left after the harvest','s2 是拾取收割后遗留的谷穗。'),Q('glean',3,1,'Which task involves gleaning clues?','combining scattered notes to infer what happened','copying one complete answer without reading','painting a wall with glaze','combining scattered notes to infer what happened','零散线索汇聚成判断，属于 glean。'),Q('glean',4,2,'The historical sense of glean is associated with?','collecting leftover grain','making pottery shiny','governing a country','collecting leftover grain','该词最初与收集遗落谷物有关。')]});
D('gleeful',{etymology:E('Gleeful is formed from glee, an Old English word for joy, plus -ful “full of.” It can describe joyful excitement or, in context, pleasure at another person’s failure.','gleeful'),contexts:[C('gleeful.s2','竞赛反应','When the rival team’s winning goal was ruled offside, the home supporters gave a gleeful cheer that sounded more like relief than sportsmanship.','对手队的制胜球被判越位后，主场球迷兴高采烈地欢呼起来，听上去更像幸灾乐祸，而非体育精神。','When the rival team’s winning goal was ruled offside / the home supporters gave a gleeful cheer / that sounded more like relief / than sportsmanship.','gleeful 在此因对手受挫而快乐，带有幸灾乐祸意味。','欢呼来自对方进球被取消，符合 s2。')],mistakes:[M('The gleeful rivals congratulated their opponents warmly and were genuinely disappointed when the other team lost.','The disappointed rivals congratulated their opponents warmly after the other team lost.','为对方失利而开心才是此处 s2；句中却明确失望。')],quiz:[Q('gleeful',1,1,'A gleeful child at a birthday party is?','full of happy excitement','quietly angry at everyone','made of glass','full of happy excitement','s1 表示欢欣雀跃。'),Q('gleeful',2,2,'A gleeful reaction to a rival’s mistake may be?','pleased because the rival failed','sad because the rival succeeded','unaware of the event','pleased because the rival failed','s2 指因别人倒霉而高兴。'),Q('gleeful',3,1,'Which scene is gleeful in the ordinary joyful sense?','a child laughing at a surprise party','a clerk quietly filing a form','a frozen lake at dawn','a child laughing at a surprise party','惊喜派对中的笑声体现愉悦。'),Q('gleeful',4,2,'A gleeful taunt after an opponent slips suggests?','unkind pleasure at the opponent’s mishap','deep sympathy without amusement','a neutral weather report','unkind pleasure at the opponent’s mishap','嘲笑对手意外体现幸灾乐祸。')]});
D('glen',{etymology:E('Glen comes from Scottish Gaelic gleann and Irish gleann, meaning a valley. In English it commonly names a long, narrow valley, often with a stream.','glen'),contexts:[C('glen.s1','苏格兰地形','A footpath followed the stream through the glen, where steep green slopes sheltered the cottages from the wind.','一条步道沿溪流穿过幽谷，陡峭的绿坡替小屋挡住了风。','A footpath followed the stream / through the glen / where steep green slopes / sheltered the cottages from the wind.','glen 指狭长山谷，常见于苏格兰和爱尔兰地名。','溪流穿行于两侧山坡之间，形成幽谷地形。')],mistakes:[M('The hikers crossed the glen, a broad treeless plateau with no valley sides or stream.','The hikers crossed the plateau, a broad high area with no valley sides.','无山谷两侧的高原不是 glen。')],quiz:[Q('glen',1,1,'A glen is a?','long narrow valley','high glass tower','type of cotton cloth','long narrow valley','glen 常指狭长山谷。'),Q('glen',2,1,'A stream may run through a glen between?','sloping valley sides','two rows of laboratory beakers','the fibres of a cotton gin','sloping valley sides','幽谷常有溪流在山坡之间流过。'),Q('glen',3,1,'The word glen is especially associated with?','Scotland and Ireland','deserts in central Asia only','the floor of the ocean','Scotland and Ireland','该词常见于苏格兰、爱尔兰地名。'),Q('glen',4,1,'Which landscape is most likely a glen?','a narrow green valley with a stream','a flat treeless plain above all hills','a glass furnace','a narrow green valley with a stream','狭长且有溪流的山谷符合 glen。')]});
D('glial',{etymology:E('Glial is formed from glia, from Greek glia “glue,” plus -al. It describes glia, the non-neuronal cells that support, protect, and maintain neurons in nervous tissue.','glial'),contexts:[C('glial.s1','神经科学','The study tracked glial cells around the injury site because these support cells help maintain the local environment for surviving neurons.','研究追踪了损伤部位周围的神经胶质细胞，因为这些支持细胞有助于维持幸存神经元的局部环境。','The study tracked glial cells around the injury site / because these support cells / help maintain the local environment / for surviving neurons.','glial 修饰 cells，指与神经胶质有关的。','句中细胞支持和维持神经元，符合定义。')],mistakes:[M('The glial cells transmitted every nerve impulse as the neurons themselves, with no supporting role.','The neuronal cells transmitted nerve impulses, while glial cells supported and maintained the tissue.','glia 主要承担支持、保护和维持作用，不应与神经元的传导功能混同。')],quiz:[Q('glial',1,1,'Glial cells are found in?','nervous tissue around neurons','glass furnaces','cotton seed pods','nervous tissue around neurons','glial 与神经胶质细胞有关。'),Q('glial',2,1,'A major role of glial cells is to?','support and protect neurons','produce cotton fibres','govern a city','support and protect neurons','神经胶质细胞支持并保护神经元。'),Q('glial',3,1,'Which phrase uses glial correctly?','glial support cells in the brain','glial cotton checks on a shirt','glial glaze on a ceramic bowl','glial support cells in the brain','脑内支持细胞可称 glial cells。'),Q('glial',4,1,'The root glia is historically associated with?','glue','ice','juniper','glue','希腊语 glia 的本义与“胶”相关。','word-formation')]});
D('glider',{etymology:E('Glider is formed from glide plus the agent or instrument suffix -er. It most often means an unpowered aircraft that stays aloft by gliding; it can also mean its pilot.','glider'),contexts:[C('glider.s2','航空俱乐部','The glider circled the ridge in silence while its pilot searched for rising air currents that could keep the aircraft aloft.','滑翔员驾驶滑翔机无声地绕着山脊飞行，同时寻找能让飞机保持升空的上升气流。','The glider circled the ridge in silence / while its pilot searched / for rising air currents / that could keep the aircraft aloft.','glider 在句首指驾驶滑翔机的人，即滑翔员。','后文称其为 pilot，明确对应 s2。')],mistakes:[M('The glider pilot started the aircraft’s powerful engine to climb, although the glider had no engine.','The glider pilot used rising air to climb because the glider had no engine.','无动力滑翔机依靠气流而非发动机飞行。')],quiz:[Q('glider',1,1,'A glider aircraft flies without?','an engine','wings','a pilot or remote control','an engine','s1 指无发动机、依靠滑翔的飞机。'),Q('glider',2,2,'A glider may also be?','the person who flies the aircraft','the engine itself','the ridge beneath it','the person who flies the aircraft','s2 可指驾驶滑翔机的人。'),Q('glider',3,1,'What helps a glider stay aloft?','rising air currents','a cotton sail full of water','a furnace beneath the wings','rising air currents','滑翔机可借助上升气流保持飞行。'),Q('glider',4,2,'The glider scanned the ridge for thermals. Here glider refers to?','its pilot','the thermal current','the unpowered aircraft only','its pilot','句中 glider 作人称名词，指飞行员。')]});
D('gliding',{etymology:E('Gliding is the present participle of glide, from an Old English verb meaning move smoothly or slip away. As an adjective it describes smooth, seemingly effortless movement.','gliding'),contexts:[C('gliding.s1','舞蹈动作','The skater made a gliding turn across the rink, transferring her weight so smoothly that the blade barely seemed to touch the ice.','滑冰者在冰场上做了一个滑行转身，重心转换如此平稳，冰刀似乎几乎没有碰到冰面。','The skater made a gliding turn across the rink / transferring her weight so smoothly / that the blade barely seemed / to touch the ice.','gliding 修饰 turn，突出平稳、轻松的移动感。','动作平顺，符合 gliding 的描述。')],mistakes:[M('The skater made a gliding turn by jerking to a complete stop at every centimetre.','The skater made a jerky turn by stopping repeatedly at every centimetre.','反复急停的动作并不平滑，不能称为 gliding。')],quiz:[Q('gliding',1,1,'A gliding movement is?','smooth and seemingly effortless','rough and repeatedly interrupted','a process of making pottery shiny','smooth and seemingly effortless','gliding 描写平稳滑行。'),Q('gliding',2,1,'Which motion looks gliding?','a dancer moving across the floor without visible jolts','a cart bumping over every stone','a person chopping wood','a dancer moving across the floor without visible jolts','没有明显颠簸的移动显得流畅。'),Q('gliding',3,1,'A gliding flight usually involves?','smooth movement through the air','a cotton machine separating seeds','an engine firing at full power at every instant','smooth movement through the air','滑翔是平稳的空中移动。'),Q('gliding',4,1,'In “a gliding shadow,” gliding describes how the shadow?','moves smoothly across a surface','shines with a harsh glare','is made of glass','moves smoothly across a surface','形容词说明影子平滑地移动。')]});
D('glidingly',{etymology:E('Glidingly is formed from gliding plus -ly. It is a rare adverb meaning smoothly or in a way that resembles gliding.','glidingly'),contexts:[C('glidingly.s1','动作描写','The heron moved glidingly along the shallow bank, each careful step so fluid that the reeds barely stirred.','苍鹭沿浅滩滑行般地移动，每一步都十分流畅，几乎没有惊动芦苇。','The heron moved glidingly along the shallow bank / each careful step so fluid / that the reeds / barely stirred.','glidingly 修饰 moved，表示平稳流畅地移动。','动作轻缓流畅，符合该少见副词义。')],mistakes:[M('The cart rolled glidingly over the stones, jolting violently and stopping after every inch.','The cart rolled jerkily over the stones, jolting and stopping after every inch.','猛烈颠簸并频繁停下，不是平稳滑行。')],quiz:[Q('glidingly',1,1,'To move glidingly is to move?','smoothly, as if sliding through air','in abrupt stops and jolts','with a loud metallic crash','smoothly, as if sliding through air','glidingly 表示像滑行一样平稳地。'),Q('glidingly',2,1,'Which adverb best describes a swan crossing still water without splashing?','glidingly','fractiously','glaringly','glidingly','天鹅平稳滑过水面，可用 glidingly 描述。'),Q('glidingly',3,1,'In “the curtain drifted glidingly,” the word modifies?','the manner of drifting','the curtain’s colour','the age of the building','the manner of drifting','副词修饰 drifted，说明移动方式。'),Q('glidingly',4,1,'What is the base idea in glidingly?','smooth gliding movement','harsh brightness','a glass coating','smooth gliding movement','该词由 gliding 加副词后缀构成。','word-formation')]});
D('glisten',{etymology:E('Glisten is related to Old English glisian and Germanic words for shining or glittering. It usually means shine softly because a surface is moist, oily, or polished.','glisten'),contexts:[C('glisten.s1','雨后花园','After the shower, droplets made the spiderweb glisten in the early light, each strand visible between the wet leaves.','阵雨过后，水珠让蛛网在晨光中闪着湿润的光，每根丝线都清晰可见。','After the shower / droplets made the spiderweb glisten / in the early light / each strand visible between the wet leaves.','glisten 表示因湿润或反光而柔和发亮。','水珠附在蛛网上并反射晨光，符合此义。')],mistakes:[M('The dry, dusty stone glistened with moisture even though no liquid or polish touched its surface.','The dry, dusty stone looked dull because no moisture or polish touched its surface.','没有湿润、油脂或抛光造成反光时，通常不会 glisten。')],quiz:[Q('glisten',1,1,'A surface that glistens?','shines softly, often with moisture','makes no light visible at all','breaks into cotton fibres','shines softly, often with moisture','glisten 常指表面带湿光地闪亮。'),Q('glisten',2,1,'Rain may make leaves glisten because?','water droplets reflect the light','the leaves become glassware','the rain freezes into cotton','water droplets reflect the light','叶面水珠反光会使其发亮。'),Q('glisten',3,1,'Which image fits glisten?','oil shining softly on a polished surface','a completely matte wall in darkness','a loud engine accelerating','oil shining softly on a polished surface','油脂或抛光表面可柔和发亮。'),Q('glisten',4,1,'A runner’s skin may glisten after exercise because it is?','damp with perspiration','covered in dry dust only','made from pottery glaze','damp with perspiration','汗水使皮肤表面带湿光。')]});
D('gloat',{etymology:E('Gloat is of Scandinavian origin, related to Norwegian dialectal glota “stare” and Swedish glo. In English it means dwell on a success or another person’s misfortune with smug satisfaction.','gloat'),contexts:[C('gloat.s1','体育竞赛','After his team won, Marco avoided gloating over the visiting players and instead thanked them for a close, well-played match.','球队获胜后，马可没有对客队球员幸灾乐祸地炫耀，而是感谢他们打了一场势均力敌的精彩比赛。','After his team won / Marco avoided gloating over the visiting players / and instead thanked them / for a close, well-played match.','gloat 常指对胜利或他人失利表现出不友善的得意。','他刻意避免炫耀胜利，呼应 gloat 的负面语气。')],mistakes:[M('She gloated over her colleague’s promotion and sincerely celebrated the colleague’s achievement without any smugness.','She congratulated her colleague on the promotion without gloating.','真诚祝贺且毫无得意不属于幸灾乐祸式的 gloat。')],quiz:[Q('gloat',1,1,'To gloat over a rival’s loss is to?','show unkind satisfaction about it','quietly repair the rival’s equipment','forget the result immediately','show unkind satisfaction about it','gloat 带有幸灾乐祸、得意的意味。'),Q('gloat',2,1,'Which behaviour is gloating?','taunting an opponent after winning','shaking hands respectfully after a match','helping a rival recover a dropped bag','taunting an opponent after winning','胜后嘲讽对手是得意炫耀。'),Q('gloat',3,1,'A considerate winner should avoid?','gloating about another team’s defeat','thanking the opposing players','acknowledging a close game','gloating about another team’s defeat','避免对他人失利幸灾乐祸。'),Q('gloat',4,1,'Someone who gloats may seem?','smug and unkind','quietly compassionate','strictly neutral','smug and unkind','该动词通常带有不友善的满足感。')]});
D('glossy',{etymology:E('Glossy is formed from gloss plus -y; gloss is related to shine. It describes a smooth shiny surface and can describe expensive magazines full of polished pictures.','glossy'),contexts:[C('glossy.s2','媒体评论','The glossy magazine showed perfect kitchens and smiling families but devoted little space to the housing costs behind those images.','这本华而不实的杂志展示完美厨房和笑容满面的家庭，却很少提及这些画面背后的住房成本。','The glossy magazine showed perfect kitchens and smiling families / but devoted little space / to the housing costs / behind those images.','glossy 在此修饰 magazine，指图片精美、表面光鲜的杂志。','内容只呈现理想化画面而回避现实问题，符合 s2。')],mistakes:[M('The glossy magazine contained no photographs, used rough newsprint, and appeared as a plain text-only pamphlet.','The text-only pamphlet was not a glossy magazine filled with polished pictures.','无图片且用粗糙纸张的纯文字小册子不符合此处 glossy magazine 的义项。')],quiz:[Q('glossy',1,1,'A glossy photograph has a surface that is?','smooth and shiny','rough and furry','transparent like clean air','smooth and shiny','s1 描写表面光滑发亮。'),Q('glossy',2,2,'A glossy magazine is often?','expensive and filled with polished pictures','a blank handwritten notebook','a cotton-separating machine','expensive and filled with polished pictures','s2 指图片精美、常较昂贵的杂志。'),Q('glossy',3,1,'Which object could be glossy?','a polished brochure cover','a matte uncoated stone','a soft woollen sock','a polished brochure cover','抛光封面有光泽。'),Q('glossy',4,2,'Calling coverage “glossy” can suggest it?','presents an attractive surface while avoiding harder details','contains only technical equations','is printed on transparent glass','presents an attractive surface while avoiding harder details','华而不实的呈现会强调漂亮表面、淡化难题。')]});
D('glucose',{etymology:E('Glucose was coined in French from Greek glykys “sweet,” with a chemical naming ending. It is a simple sugar (a monosaccharide) carried in blood and used by cells for energy.','glucose'),contexts:[C('glucose.s1','血糖检测','The nurse measured the patient’s blood glucose before breakfast and recorded the result alongside the prescribed insulin dose.','护士在早餐前测量了患者的血糖，并把结果与规定的胰岛素剂量一同记录。','The nurse measured the patient’s blood glucose / before breakfast / and recorded the result / alongside the prescribed insulin dose.','glucose 指血液中可测量的葡萄糖，一种供细胞利用的单糖。','血糖检测与胰岛素管理直接涉及 glucose。')],mistakes:[M('Glucose is a complex protein that carries oxygen through the blood to the lungs.','Glucose is a simple sugar that cells use for energy; haemoglobin carries oxygen in blood.','葡萄糖是糖类，不是运输氧气的蛋白质。')],quiz:[Q('glucose',1,1,'Glucose is a?','simple sugar used by cells for energy','structural protein in glass','type of cotton fibre','simple sugar used by cells for energy','葡萄糖是细胞可利用的单糖。'),Q('glucose',2,1,'A blood-glucose test measures?','the amount of glucose in blood','the number of glial cells in the brain','the weight of a glassware shelf','the amount of glucose in blood','血糖检测测量血液中的葡萄糖水平。'),Q('glucose',3,1,'Which formula belongs to glucose?','C6H12O6','NaCl only','Fe2O3','C6H12O6','葡萄糖分子式为 C6H12O6。'),Q('glucose',4,1,'Cells use glucose primarily as?','an energy source','a cotton cloth pattern','a ceramic glaze','an energy source','葡萄糖为细胞供能。')]});
D('glutamate',{etymology:E('Glutamate is formed from glutamic acid plus the chemical suffix -ate, naming a salt or ester of that acid. Monosodium glutamate is a familiar flavour enhancer.','glutamate'),contexts:[C('glutamate.s1','食品标签','The ingredient label listed monosodium glutamate, a glutamate salt used to enhance savoury flavour in the packaged soup.','配料表列出了谷氨酸一钠，这是一种用于增强包装汤品鲜味的谷氨酸盐。','The ingredient label listed monosodium glutamate / a glutamate salt / used to enhance savoury flavour / in the packaged soup.','glutamate 指谷氨酸的盐或酯；味精是常见实例。','句中指出谷氨酸盐用作鲜味增强剂。')],mistakes:[M('Monosodium glutamate is a type of cotton fibre added to soup to make it taste savoury.','Monosodium glutamate is a glutamate salt added to some foods as a flavour enhancer.','味精是谷氨酸盐，不是棉纤维。')],quiz:[Q('glutamate',1,1,'Glutamate is a salt or ester of?','glutamic acid','glucose','gesso','glutamic acid','glutamate 来自谷氨酸。'),Q('glutamate',2,1,'Monosodium glutamate is commonly used to?','enhance savoury flavour','make glass transparent','turn cotton into gingham','enhance savoury flavour','味精常用于增强鲜味。'),Q('glutamate',3,1,'Which label contains a glutamate compound?','monosodium glutamate','cotton gin','glacial till','monosodium glutamate','谷氨酸一钠属于谷氨酸盐。'),Q('glutamate',4,1,'The suffix -ate in a chemical name can mark?','a salt or related compound','a person who governs','a narrow valley','a salt or related compound','此处 -ate 用于化合物名称。','word-formation')]});
D('glycoprotein',{etymology:E('Glycoprotein combines glyco-, from Greek glykys “sweet” and used for sugar, with protein. It names a molecule in which sugar groups are attached to a protein.','glycoprotein'),contexts:[C('glycoprotein.s1','细胞生物学','The laboratory tagged a cell-surface glycoprotein with a fluorescent marker so researchers could observe how it moved between neighbouring cells.','实验室用荧光标记标记了一种细胞表面糖蛋白，以便研究人员观察它如何在相邻细胞之间移动。','The laboratory tagged a cell-surface glycoprotein / with a fluorescent marker / so researchers could observe / how it moved between neighbouring cells.','glycoprotein 指糖链与蛋白质相连形成的分子。','细胞表面分子带有糖链，符合糖蛋白定义。')],mistakes:[M('A glycoprotein contains no protein at all; it is simply a free glucose crystal on the cell surface.','A glycoprotein contains a protein with one or more attached sugar groups.','该词明确包含蛋白质与糖链连接，不是单独的葡萄糖晶体。')],quiz:[Q('glycoprotein',1,1,'A glycoprotein is a molecule made of?','protein with attached sugar groups','glucose alone without protein','glass coated with cotton','protein with attached sugar groups','glyco- 表示糖，protein 表示蛋白质。'),Q('glycoprotein',2,1,'Where are many glycoproteins found?','on cell surfaces','inside cotton gin gears only','on the surface of glaciers only','on cell surfaces','许多糖蛋白位于细胞表面。'),Q('glycoprotein',3,1,'Which description distinguishes a glycoprotein from glucose?','it contains a protein linked to sugar','it is always a single free sugar','it is a type of ceramic coating','it contains a protein linked to sugar','糖蛋白含蛋白质与糖链的连接。'),Q('glycoprotein',4,1,'In glycoprotein, glyco- refers to?','sugar','ice','a valley','sugar','glyco- 与糖有关。','word-formation')]});
D('glycoside',{etymology:E('Glycoside is formed from glyco-, relating to sugar, and the chemical suffix -ide. It denotes a compound in which a sugar is linked to a non-sugar group; many occur in plants.','glycoside'),contexts:[C('glycoside.s1','植物化学','The botanist isolated a glycoside from the leaf extract and tested how its sugar-linked structure changed when an enzyme was added.','植物学家从叶片提取物中分离出一种糖苷，并检测加入酶后其糖连接结构如何变化。','The botanist isolated a glycoside from the leaf extract / and tested how its sugar-linked structure / changed / when an enzyme was added.','glycoside 指糖与非糖基团相连形成的化合物。','植物叶片提取物中的糖连接分子符合糖苷定义。')],mistakes:[M('The isolated glycoside consisted only of a free protein chain with no sugar group or sugar bond.','The isolated compound was a protein rather than a glycoside because it had no sugar group.','没有糖连接的蛋白质不是 glycoside。')],quiz:[Q('glycoside',1,1,'A glycoside contains?','a sugar linked to a non-sugar group','only a free cotton fibre','a glass panel with no molecules','a sugar linked to a non-sugar group','糖苷由糖与非糖基团连接形成。'),Q('glycoside',2,1,'Where are many naturally occurring glycosides found?','in plants','in steel bridge beams','in cotton cloth patterns only','in plants','植物中常见各种糖苷。'),Q('glycoside',3,1,'An enzyme study of a glycoside may examine?','its sugar-linked structure','the colour of a glider pilot’s uniform','the shape of a valley','its sugar-linked structure','糖苷研究会关注糖基连接结构。'),Q('glycoside',4,1,'The element glyco- points to?','sugar','glass','glacier','sugar','glyco- 表示糖相关。','word-formation')]});
D('gnaw',{etymology:E('Gnaw comes from Old English gnagan, “to bite or scrape with the teeth,” from a Germanic root. It can describe persistent biting, continuing worry, or slow erosion.','gnaw'),contexts:[C('gnaw.s2','心理描写','The unresolved question continued to gnaw at Lila during the journey, returning whenever the conversation fell quiet.','那个悬而未决的问题一路折磨着莉拉；每当谈话安静下来，它就再次浮上心头。','The unresolved question continued to gnaw at Lila / during the journey / returning whenever / the conversation fell quiet.','gnaw at 在此比喻持续困扰、折磨某人。','问题反复出现并令人不安，符合 s2。')],mistakes:[M('The unresolved worry gnawed at him, but it disappeared instantly and never troubled him again.','The unresolved worry stopped gnawing at him once it was settled.','一闪而过且不再造成困扰的念头，不符合持续折磨的 s2。')],quiz:[Q('gnaw',1,1,'A mouse gnaws wood by?','biting it repeatedly with its teeth','painting it with glaze','measuring its temperature','biting it repeatedly with its teeth','s1 指反复啃咬以磨损物体。'),Q('gnaw',2,2,'A worry that gnaws at someone?','continues to trouble them','makes them laugh once and vanish','turns them into a glider','continues to trouble them','s2 是持续使人烦恼。'),Q('gnaw',3,1,'Which animal behaviour is gnawing?','a beaver repeatedly chewing a branch','a giraffe swallowing a leaf whole','a fish gliding without biting','a beaver repeatedly chewing a branch','反复咬木头是啃咬。'),Q('gnaw',4,2,'A doubt gnawed at the witness through the night. The doubt?','kept causing worry','was physically eaten by the witness','became a piece of glassware','kept causing worry','句中表达疑虑持续困扰证人。')]});
D('goatee',{etymology:E('Goatee is a diminutive of goat, named for the small beard on the chin that resembles a goat’s beard. It commonly refers to chin hair worn with the upper lip clean-shaven.','goatee'),contexts:[C('goatee.s1','人物外貌','The actor shaved his cheeks and upper lip but kept a narrow goatee beneath his lower lip for the role.','演员刮净两颊和上唇，却为角色保留了下唇下方一小撮山羊胡。','The actor shaved his cheeks and upper lip / but kept a narrow goatee / beneath his lower lip / for the role.','goatee 指只长在下巴上的小胡子，常与干净的上唇并存。','句中明确说明下唇下方保留胡须，符合词义。')],mistakes:[M('He wore a goatee that covered both cheeks and his entire forehead but left the chin completely bare.','He wore a full beard over his cheeks and left the chin bare.','goatee 集中在下巴；覆盖额头、脸颊却不留 chin hair 与之矛盾。')],quiz:[Q('goatee',1,1,'A goatee is facial hair worn mainly?','on the chin','across the forehead','behind the ears','on the chin','goatee 指下巴上的小胡子。'),Q('goatee',2,1,'A person with a goatee may have?','a bare upper lip','a beard only on the forehead','no hair on the chin','a bare upper lip','山羊胡常只留在下巴。'),Q('goatee',3,1,'Which description fits a goatee?','a small chin beard','a long formal gown','a pair of swimming goggles','a small chin beard','下巴胡须是 goatee 的核心特征。'),Q('goatee',4,1,'The name goatee refers to resemblance to a?','goat’s beard','giraffe’s neck','glacier’s edge','goat’s beard','名称源于与山羊胡的相似。')]});
D('godsend',{etymology:E('Godsend combines God and send and has been used since early modern English for a gift or piece of good fortune regarded as sent by God. In current use it means unexpected help or luck.','godsend'),contexts:[C('godsend.s1','突发维修','When the replacement pump arrived just before the clinic’s water supply failed, it was a godsend that kept the emergency rooms operating.','替换水泵恰在诊所供水中断前送到，真是及时的帮助，让急诊室得以继续运转。','When the replacement pump arrived just before the clinic’s water supply failed / it was a godsend / that kept the emergency rooms / operating.','godsend 指意外到来、正好解决困难的帮助或好运。','设备及时到达并解决急迫问题，符合词义。')],mistakes:[M('The spare pump was a godsend because it arrived years after the clinic had closed and could not solve any problem.','The spare pump was no help because it arrived after the clinic had closed.','来得太迟且无法解决问题的东西不是及时的 godsend。')],quiz:[Q('godsend',1,1,'A godsend is?','unexpected good fortune or help','a planned inconvenience','a type of glassmaking tool','unexpected good fortune or help','godsend 指意外且及时的帮助或好运。'),Q('godsend',2,1,'A replacement pump arriving during a water outage could be a godsend because it?','solves an urgent problem at just the right time','makes the outage last longer','is a type of cotton fabric','solves an urgent problem at just the right time','它及时解决迫切困难，正符合该词。'),Q('godsend',3,1,'Which event is a godsend to a stranded traveller?','an unexpected rescue vehicle arriving','a bus that left before the traveller arrived','a broken map with no useful route','an unexpected rescue vehicle arriving','意外救援能解决困境。'),Q('godsend',4,1,'Why might someone call a timely scholarship a godsend?','it unexpectedly removes a serious financial difficulty','it prevents them from studying','it is a shiny pottery coating','it unexpectedly removes a serious financial difficulty','奖学金及时缓解经济困难。')]});
D('goggles',{etymology:E('Goggles is the plural of goggle, probably related to a dialect verb meaning stare with bulging eyes. The word names close-fitting protective eyewear, often with side shields.','goggles'),contexts:[C('goggles.s1','实验室安全','Before handling the solution, the student put on sealed goggles that covered the sides of the eyes as well as the front.','处理溶液前，学生戴上密封护目镜，镜片既遮住眼睛前方，也保护两侧。','Before handling the solution / the student put on sealed goggles / that covered the sides of the eyes / as well as the front.','goggles 是贴合眼部、用于保护眼睛的护目镜。','实验室中密封并遮挡侧面的眼镜用于防护飞溅。')],mistakes:[M('She wore goggles with no lenses or side shields while splashing the chemical toward her eyes.','She wore protective goggles with lenses and side shields while handling the chemical.','没有镜片和侧边防护的用品无法充当护目镜。')],quiz:[Q('goggles',1,1,'Goggles are worn to?','protect the eyes','cover the waist','filter cotton seeds','protect the eyes','goggles 指护目镜或风镜。'),Q('goggles',2,1,'Which activity may require goggles?','working with splashing chemicals','reading a map in a dry office only','weaving gingham at home','working with splashing chemicals','处理飞溅化学品时需要护目镜。'),Q('goggles',3,1,'Protective goggles often have?','a close fit and side shields','a long handle and curved blade','a glass coating on pottery','a close fit and side shields','护目镜通常贴合面部并有侧边遮挡。'),Q('goggles',4,1,'Swim goggles help keep water away from?','the eyes','the cotton seeds','the bridge girder','the eyes','游泳镜用于保护眼睛不进水。')]});
D('goldfish',{etymology:E('Goldfish combines gold and fish, named for the familiar golden-orange colour of the domesticated fish. It is a small freshwater member of the carp family.','goldfish'),contexts:[C('goldfish.s1','水族饲养','The goldfish stayed in a filtered freshwater tank, and the owner tested ammonia levels before changing part of the water.','金鱼养在有过滤设备的淡水缸中，主人先检测氨含量，再更换部分缸水。','The goldfish stayed in a filtered freshwater tank / and the owner tested ammonia levels / before changing / part of the water.','goldfish 指常见的鲤科淡水观赏鱼。','淡水鱼缸的饲养情景与金鱼相符。')],mistakes:[M('The goldfish was a saltwater mammal that breathed air and lived permanently on dry land.','The goldfish was a freshwater fish kept in an aquarium.','金鱼是淡水鱼，不是海洋哺乳动物或陆生动物。')],quiz:[Q('goldfish',1,1,'A goldfish is a small?','freshwater fish','African ape','glandular cell','freshwater fish','金鱼是鲤科淡水鱼。'),Q('goldfish',2,1,'A goldfish tank should contain?','freshwater','molten glass','cotton lint','freshwater','金鱼生活在淡水中。'),Q('goldfish',3,1,'The name goldfish often refers to its?','golden or orange colour','ability to make glass','long neck','golden or orange colour','名称与常见金橙色有关。'),Q('goldfish',4,1,'Which pet is a goldfish?','a small carp-family aquarium fish','a gosling learning to fly','a gibbon in a forest','a small carp-family aquarium fish','金鱼属于鲤科，是常见观赏鱼。')]});

D('goldsmith',{etymology:E('Goldsmith combines gold with smith, from Old English smith “worker or metalworker.” It names a craftworker who shapes gold into jewellery, vessels, or other objects.','goldsmith'),contexts:[C('goldsmith.s1','珠宝修复','The goldsmith soldered a broken clasp, polished the ring, and checked that the repaired setting held the small stone securely.','金匠焊好了断裂的搭扣，抛光戒指，并检查修复后的镶座是否牢固地托住小宝石。','The goldsmith soldered a broken clasp / polished the ring / and checked that the repaired setting / held the small stone securely.','goldsmith 指加工黄金或制作金饰的工匠。','焊接、抛光和修理首饰都是金匠工作。')],mistakes:[M('The goldsmith made the ring from molten cotton fibres and never worked with any metal.','The goldsmith made the ring from gold and shaped the metal into jewellery.','棉纤维不是金属，不能构成金匠制作的金饰。')],quiz:[Q('goldsmith',1,1,'A goldsmith works mainly with?','gold and other jewellery metals','glacier ice','cotton seed fibres','gold and other jewellery metals','goldsmith 是加工黄金的工匠。'),Q('goldsmith',2,1,'A goldsmith might repair a?','gold ring setting','glen stream','pair of glial cells','gold ring setting','修理金戒指属于金匠工作。'),Q('goldsmith',3,1,'Which task suits a goldsmith?','shaping gold into a pendant','weaving cotton gingham','measuring blood glucose','shaping gold into a pendant','金匠把黄金加工成首饰。'),Q('goldsmith',4,1,'The element smith in goldsmith means a?','metalworker or craftworker','mountain valley','sweet sugar','metalworker or craftworker','smith 表示工匠、金属工匠。','word-formation')]});
D('goodby',{etymology:E('Goodby is an accepted variant of goodbye, which developed from the farewell phrase “God be with ye.” The word is said when parting from someone; goodbye is the more usual modern spelling.','goodby'),contexts:[C('goodby.s1','机场告别','At the gate, Nia waved and said goodby to her brother before he boarded the late flight to Toronto.','在登机口，妮娅挥手向弟弟道别，然后他登上了飞往多伦多的晚班飞机。','At the gate / Nia waved and said goodby to her brother / before he boarded / the late flight to Toronto.','goodby 是 goodbye 的可接受拼写变体，表示分别时说的“再见”。','登机前向亲人告别，符合该词义。')],mistakes:[M('When the newly arrived guest entered the room, the host said goodby as a greeting.','When the newly arrived guest entered the room, the host said hello as a greeting.','goodby 用于离别，不是迎接刚到访者的问候语。')],quiz:[Q('goodby',1,1,'Goodby is said when?','parting from someone','welcoming someone who has just arrived','measuring a glass panel','parting from someone','goodby 用于分别告辞。'),Q('goodby',2,1,'Which situation calls for a goodby?','a passenger leaving on a train','a guest arriving at the front door','a student opening a textbook','a passenger leaving on a train','离开时可向他人说再见。'),Q('goodby',3,1,'Which statement about the spelling goodby is accurate?','It is a variant; goodbye is more usual.','It is never used in English.','It names a glassmaking tool.','It is a variant; goodbye is more usual.','goodby 是变体拼写，goodbye 更常见。'),Q('goodby',4,1,'The phrase “say goodby to a colleague” means?','bid the colleague farewell','introduce the colleague to a visitor','ask the colleague for directions','bid the colleague farewell','say goodby to someone 即向其告别。')]});
D('goodwill',{etymology:E('Goodwill combines good with will, an old word for intention or desire. It can mean friendly, cooperative feeling and, in business accounting, the value of reputation and customer relationships beyond physical assets.','goodwill'),contexts:[C('goodwill.s2','企业并购','The buyer paid for the company’s goodwill as well as its equipment, recognizing the value of its trusted name and loyal customers.','买方除设备外还为公司的商誉支付了价款，认可其可信品牌和忠实客户所带来的价值。','The buyer paid for the company’s goodwill / as well as its equipment / recognizing the value / of its trusted name and loyal customers.','goodwill 在此是会计和商业语境中的商誉。','品牌声誉和客户关系超出有形资产价值，符合 s2。')],mistakes:[M('The accountant recorded goodwill as a physical delivery truck with a registration number and engine.','The accountant recorded goodwill as an intangible value tied to reputation and customer relationships.','商誉是无形价值，不是有形车辆。')],quiz:[Q('goodwill',1,1,'Goodwill between neighbours means?','friendly and cooperative feeling','a debt owed to a bank','a type of glass coating','friendly and cooperative feeling','s1 指人与群体之间的善意。'),Q('goodwill',2,2,'A company’s goodwill may reflect?','its reputation and loyal customers','only its physical desks and trucks','the weight of its gold jewellery','its reputation and loyal customers','s2 是声誉和客户关系形成的商誉。'),Q('goodwill',3,1,'A goodwill gesture is intended to show?','friendly intention','angry retaliation','a legal sentence','friendly intention','goodwill gesture 表示善意举动。'),Q('goodwill',4,2,'Why can a buyer pay for goodwill beyond a firm’s equipment?','the firm has valuable reputation and customer ties','the equipment has no physical form','the firm is a type of government','the firm has valuable reputation and customer ties','商誉包括超出有形资产的品牌与客户价值。')]});
D('gorilla',{etymology:E('Gorilla entered modern European languages through Greek and Latin accounts of African peoples’ reports of a great ape. It names the large African ape and informally can mean a hired strongman or thug.','gorilla'),contexts:[C('gorilla.s2','犯罪报道','The nightclub owner was accused of hiring a gorilla to intimidate witnesses, a role that had nothing to do with the animal.','夜总会老板被指控雇用一名打手恐吓证人，这里的角色与动物无关。','The nightclub owner was accused / of hiring a gorilla / to intimidate witnesses / a role that had nothing to do with the animal.','gorilla 在此口语中指受雇恐吓他人的彪形大汉或打手。','雇来威胁证人，符合 s2 的贬义人称用法。')],mistakes:[M('The nightclub hired a gorilla to guard the witnesses, and the contract described the employee as a gentle African ape.','The nightclub hired a strongman to guard the witnesses.','此处指受雇人员而非动物；不能把人称义当成真正的猿类。')],quiz:[Q('gorilla',1,1,'A gorilla is a large?','African ape','freshwater fish','small goose','African ape','s1 指非洲大型猿类。'),Q('gorilla',2,2,'In an informal crime report, a gorilla may be?','a hired strongman used to threaten people','a zoologist studying apes','a friendly shopkeeper','a hired strongman used to threaten people','s2 是打手、歹徒的比喻用法。'),Q('gorilla',3,1,'Where do wild gorillas live?','in African forests','in the open ocean','only in European glens','in African forests','大猩猩原生于非洲森林。'),Q('gorilla',4,2,'“The gang sent a gorilla to intimidate the witness.” Here gorilla is?','a threatening hired man','an ape kept in a zoo','a kind of glider','a threatening hired man','语境中的 intimidate 标明是打手义。')]});
D('gosling',{etymology:E('Gosling combines goose with the diminutive suffix -ling. It means a young goose that has not yet reached full growth.','gosling'),contexts:[C('gosling.s1','农场观察','The gosling stayed close behind its mother as the flock crossed the yard from the pond to the sheltered feeding area.','鹅雏紧跟母鹅身后，鹅群从池塘穿过院子走向避风的喂食区。','The gosling stayed close behind its mother / as the flock crossed the yard / from the pond / to the sheltered feeding area.','gosling 指尚未长成的小鹅。','它跟随母鹅活动，符合幼鹅情景。')],mistakes:[M('The gosling was a fully grown adult goose that had stopped growing years earlier.','The gosling was a young goose that had not yet fully grown.','完全长成的成年鹅不再是 gosling。')],quiz:[Q('gosling',1,1,'A gosling is a young?','goose','giraffe','goldsmith','goose','gosling 指小鹅。'),Q('gosling',2,1,'A gosling is likely to stay near?','its mother in the flock','a cotton gin in a factory','a glacier’s edge','its mother in the flock','幼鹅常跟随母鹅。'),Q('gosling',3,1,'Which bird grows into a gosling?','a goose','a gorilla','a goldfish','a goose','gosling 是 goose 的幼鸟名称。'),Q('gosling',4,1,'The suffix -ling in gosling indicates?','a young or small form','a glass coating','a government office','a young or small form','-ling 常形成幼小个体名称。','word-formation')]});
D('gossamer',{etymology:E('Gossamer is a Middle English word associated with fine spider silk floating in the air; its deeper origin is uncertain. It also describes something extremely light, thin, or delicate.','gossamer'),contexts:[C('gossamer.s2','织物描写','She wore a gossamer scarf so light and delicate that a small breeze lifted its edge as she crossed the courtyard.','她围着一条轻薄纤柔的薄纱围巾，穿过庭院时，微风便吹起了它的一角。','She wore a gossamer scarf / so light and delicate / that a small breeze / lifted its edge as she crossed the courtyard.','gossamer 在此作形容词，表示极轻、极薄、纤柔。','薄巾轻得被微风吹起，符合 s2。')],mistakes:[M('The gossamer cloth was a rigid, heavy sheet of steel that could not move in a breeze.','The heavy cloth was not gossamer because it was rigid and could not move in a breeze.','沉重、坚硬的材料不符合 gossamer 的轻薄纤柔义。')],quiz:[Q('gossamer',1,1,'Gossamer may first bring to mind?','fine floating spider silk','a steel bridge girder','a thick cotton bale','fine floating spider silk','s1 可指飘浮的细蛛丝。'),Q('gossamer',2,2,'A gossamer veil is?','extremely light and delicate','heavy and made of stone','bright enough to hurt the eyes','extremely light and delicate','s2 描写轻薄纤柔。'),Q('gossamer',3,1,'Which image fits gossamer?','thin threads drifting in morning air','a dense metal wall','a thick wet clay pot','thin threads drifting in morning air','空中飘动的细蛛丝是典型意象。'),Q('gossamer',4,2,'A gossamer fabric would be easy for?','a breeze to lift','a person to use as a steel beam','a goldsmith to melt into gold','a breeze to lift','轻薄织物容易被微风吹动。')]});
D('gothic',{etymology:E('Gothic comes from Latin Gothicus, “of the Goths.” It describes the medieval architectural style with pointed arches and tall windows, and can name that style or gloomy, supernatural literature.','gothic'),contexts:[C('gothic.s2','文学评论','The novel’s gothic mood came from its isolated manor, unexplained footsteps, and a family secret that surfaced after midnight.','这部小说的哥特式氛围来自偏僻庄园、无法解释的脚步声，以及午夜后浮出的家族秘密。','The novel’s gothic mood came from its isolated manor / unexplained footsteps / and a family secret / that surfaced after midnight.','gothic 在此指阴郁、带有神秘或超自然色彩的文学风格。','孤立庄园与午夜秘密构成哥特式文学气氛。')],mistakes:[M('The novel’s gothic mood came from its cheerful picnic, bright comedy, and complete absence of mystery or danger.','The novel’s cheerful mood came from its picnic and comedy, not from gothic mystery.','明快欢快且无神秘感的内容与此处 gothic 氛围不符。')],quiz:[Q('gothic',1,1,'Gothic architecture often has?','pointed arches and tall windows','flat cotton checks','round fish gills','pointed arches and tall windows','s1 指中世纪哥特式建筑特征。'),Q('gothic',2,2,'A gothic novel may feature?','gloom, secrets, and the supernatural','only cheerful farm recipes','technical notes on glucose','gloom, secrets, and the supernatural','s2 可指阴郁神秘的文学风格。'),Q('gothic',3,1,'Which building is most likely gothic?','a medieval cathedral with pointed arches','a modern greenhouse with a flat roof','a small wooden fishing boat','a medieval cathedral with pointed arches','尖拱是哥特式建筑的标志。'),Q('gothic',4,2,'A gothic atmosphere is usually?','dark and mysterious','brightly clinical and routine','entirely comic with no suspense','dark and mysterious','文学中的 gothic 气氛常阴郁神秘。')]});
D('gouache',{etymology:E('Gouache came into English from French gouache and Italian guazzo, ultimately related to a word for watercolour. It is an opaque water-based paint or a work made with it.','gouache'),contexts:[C('gouache.s1','绘画技法','The illustrator layered opaque gouache over the pencil sketch, using white paint to restore a bright highlight on the dark jacket.','插画师在铅笔草图上叠加不透明水粉颜料，并用白色颜料在深色外套上补出明亮高光。','The illustrator layered opaque gouache over the pencil sketch / using white paint / to restore a bright highlight / on the dark jacket.','gouache 是加白粉后呈不透明效果的水性颜料，也可指其画作。','用水粉覆盖草图并修复高光，符合媒材义。')],mistakes:[M('The illustrator chose transparent oil paint called gouache, which could not cover the dark pencil lines.','The illustrator chose opaque water-based gouache, which could cover the dark pencil lines.','gouache 的常见特征是不透明水性颜料，不是透明油画颜料。')],quiz:[Q('gouache',1,1,'Gouache is a type of?','opaque water-based paint','juniper-flavoured spirit','glassmaking furnace','opaque water-based paint','gouache 是不透明水性颜料。'),Q('gouache',2,1,'An artist may add white to gouache to make it?','opaque','a cotton fabric','a glacier','opaque','加白粉可使水粉颜料呈不透明效果。'),Q('gouache',3,1,'A work painted in gouache is made with?','that water-based medium','molten gold only','frozen river water','that water-based medium','gouache 也可指用该媒材完成的作品。'),Q('gouache',4,1,'Which surface could gouache cover effectively?','a dark sketch beneath an opaque layer','a deep lake beneath a glacier','cotton seeds inside a gin','a dark sketch beneath an opaque layer','不透明水粉可覆盖底层线条。')]});
D('gouge',{etymology:E('Gouge came through Old French gouge from Latin gubia, “a hollow chisel.” As a verb it means cut or force out a deep groove or hole; as a noun it can name the curved chisel or its cut.','gouge'),contexts:[C('gouge.s2','木工工具','The cabinetmaker selected a curved gouge and used it to carve a shallow channel along the edge of the wooden panel.','细木工选了一把弧刃圆凿，用它沿木板边缘凿出一条浅槽。','The cabinetmaker selected a curved gouge / and used it to carve / a shallow channel / along the edge of the wooden panel.','gouge 在此是刃口弯曲的凿子，或其凿出的槽。','弧刃工具用于木板雕刻，符合 s2。')],mistakes:[M('The carpenter used a flat soft brush called a gouge to paint a channel without cutting or shaping wood.','The carpenter used a curved gouge to cut a channel in the wood.','gouge 是凿子或凿痕，不是软毛刷。')],quiz:[Q('gouge',1,1,'To gouge a hole is to?','cut or force out a deep opening','cover it with a thin glaze','fill it with cotton','cut or force out a deep opening','s1 是凿出深洞或槽。'),Q('gouge',2,2,'A woodworker’s gouge is?','a chisel with a curved blade','a piece of gingham','a glass drinking vessel','a chisel with a curved blade','s2 指弧刃凿子。'),Q('gouge',3,1,'A tool may gouge a board by?','cutting a groove into it','polishing it without contact','freezing it into ice','cutting a groove into it','凿出沟槽是 gouge 的动词用法。'),Q('gouge',4,2,'The gouge along the panel edge is?','the groove cut into the wood','the artist’s paint colour','the person who governs the shop','the groove cut into the wood','名词可指凿出的槽。')]});
D('gourd',{etymology:E('Gourd came through French gourde from Latin cucurbita, the name of a gourd or cucumber-like plant. It names a large fruit with a hard skin, some types of which are dried and used as vessels.','gourd'),contexts:[C('gourd.s1','传统器皿','After the gourd dried, the craftworker cut a small opening, removed the seeds, and polished the hard shell into a water container.','葫芦晒干后，工匠切开一个小口，取出种子，再把坚硬外壳打磨成盛水容器。','After the gourd dried / the craftworker cut a small opening / removed the seeds / and polished the hard shell into a water container.','gourd 指皮硬的大果实，干燥后有时可作容器。','果实晒干并掏空外壳，展示了葫芦的传统用途。')],mistakes:[M('The gourd was a soft leafy herb with no fruit or hard skin, so it could not be hollowed out.','The gourd was a hard-skinned fruit that could be hollowed out after drying.','gourd 是皮硬的大果实，不是没有果实的软叶草本。')],quiz:[Q('gourd',1,1,'A gourd is a large?','hard-skinned fruit','small metal tool','young goose','hard-skinned fruit','gourd 指皮硬的大果实。'),Q('gourd',2,1,'A dried gourd can sometimes be made into?','a hollow vessel','a glassmaking furnace','a cotton flower','a hollow vessel','干葫芦可掏空作器皿。'),Q('gourd',3,1,'What part of a gourd may become a container?','its hard shell','its glial cells','its feathered wing','its hard shell','硬壳可加工成容器。'),Q('gourd',4,1,'Which object is most likely made from a gourd?','a dried hollow water flask','a steel bridge girder','a pair of goggles','a dried hollow water flask','葫芦可制成传统水壶。')]});
D('gourmand',{etymology:E('Gourmand is borrowed from French gourmand, “glutton” or “one fond of good food,” with a history that may relate to gourmet. In English it often means someone who enjoys eating heartily, sometimes to excess.','gourmand'),contexts:[C('gourmand.s1','餐桌人物','The gourmand ordered a second tasting menu, savouring every rich course even after the rest of the party had finished.','这位贪吃的食客又点了一份品鉴菜单；即使同桌的人都吃完了，他仍细细品尝每道浓郁菜品。','The gourmand ordered a second tasting menu / savouring every rich course / even after the rest of the party / had finished.','gourmand 指非常爱吃、可能吃得过量的人。','继续享用丰盛菜肴，体现 gourmand 的食客含义。')],mistakes:[M('The gourmand refused every meal and disliked food so intensely that eating was impossible.','The gourmand eagerly enjoyed the meal and asked for another course.','完全厌食与 gourmand 爱吃、常吃得多的含义相反。')],quiz:[Q('gourmand',1,1,'A gourmand is especially fond of?','eating, sometimes to excess','repairing glassware','governing a state','eating, sometimes to excess','gourmand 指爱吃、可能贪食的人。'),Q('gourmand',2,1,'Which person sounds like a gourmand?','someone who eagerly orders extra courses','someone who avoids all food','someone who only studies glaciers','someone who eagerly orders extra courses','主动点多道菜体现贪吃。'),Q('gourmand',3,1,'A gourmand may enjoy food even when?','the meal is rich and plentiful','the plate is empty before service','the food is only a glass panel','the meal is rich and plentiful','gourmand 对吃饭有强烈兴趣。'),Q('gourmand',4,1,'Gourmand differs from a trained food critic because it emphasizes?','love of eating, sometimes excessive','skill at identifying every ingredient','the profession of glassmaking','love of eating, sometimes excessive','该词着重爱吃，未必强调专业鉴赏能力。')]});
D('gourmet',{etymology:E('Gourmet is borrowed from French gourmet, historically a wine taster or connoisseur. In English it names someone with a refined taste for high-quality food and cooking.','gourmet'),contexts:[C('gourmet.s1','餐馆评价','A gourmet noticed that the sauce had been reduced slowly with roasted shallots and praised how its acidity balanced the rich fish.','一位美食家注意到酱汁用烤红葱头慢慢收浓，并称赞它的酸味平衡了肥美的鱼肉。','A gourmet noticed that the sauce had been reduced slowly / with roasted shallots / and praised how its acidity / balanced the rich fish.','gourmet 指对高品质烹饪有鉴别力的人。','他能评价酱汁的制作和味道平衡，体现鉴赏能力。')],mistakes:[M('The gourmet judged every dish only by its portion size and could not distinguish flavour or cooking quality.','The gourmet judged dishes by their flavour and cooking quality.','只看分量且不能辨别味道，不符合美食家的鉴赏特点。')],quiz:[Q('gourmet',1,1,'A gourmet is someone with?','a refined taste for high-quality food','a dislike of eating','a job making bridge beams','a refined taste for high-quality food','gourmet 指有鉴赏力的美食家。'),Q('gourmet',2,1,'A gourmet reviewing a meal may discuss?','flavour balance and cooking technique','the number of goose feathers','the weight of a cotton gin','flavour balance and cooking technique','美食家会关注味道和烹饪水平。'),Q('gourmet',3,1,'Which description fits a gourmet?','a diner who can distinguish fine ingredients and preparation','a person who eats anything without noticing taste','a mechanic who repairs governors','a diner who can distinguish fine ingredients and preparation','对食材、做法有鉴别力符合 gourmet。'),Q('gourmet',4,1,'Compared with gourmand, gourmet more strongly suggests?','discernment about food quality','eating as much as possible','a type of glassware','discernment about food quality','gourmet 着重鉴赏，区别于 gourmand 的爱吃。')]});
D('govern',{etymology:E('Govern came through Old French governer from Latin gubernare, from Greek kybernan “to steer.” It can mean rule a country, manage an organization, determine something, or require a grammatical form.','govern'),contexts:[C('govern.s4','语法教学','In the sentence “She gave him the book,” the verb gave governs the object forms him and the book in different grammatical roles.','在“She gave him the book”这句话中，动词 gave 支配宾语形式 him 和 the book，使它们承担不同语法角色。','In the sentence “She gave him the book” / the verb gave governs the object forms / him and the book / in different grammatical roles.','governs 在此是语法术语，表示动词要求或支配特定的语法形式。','动词与宾语形式的语法关系对应 s4。')],mistakes:[M('In English grammar, the verb govern means to require a grammatical form, but the example claimed it governs none despite selecting the pronoun him.','In English grammar, the verb govern means to require or select a particular grammatical form.','若动词选择了代词格等形式，就不能说它完全不支配语法形式。')],quiz:[Q('govern',1,1,'A government governs a country by?','officially running and controlling it','polishing its glassware','feeding its goldfish','officially running and controlling it','s1 指统治、治理国家。'),Q('govern',2,2,'A board may govern a university by?','controlling how the organization operates','turning it into a glen','covering it with glaze','controlling how the organization operates','s2 是管理机构的运作。'),Q('govern',3,3,'If cost governs a decision, cost?','strongly influences or determines it','is ignored completely','means a grammatical pronoun','strongly influences or determines it','s3 指支配、决定或影响。'),Q('govern',4,4,'In grammar, a verb can govern?','the form of a following word','the weather over a country','the colour of a glider','the form of a following word','s4 是语法上要求特定形式。')]});
D('governance',{etymology:E('Governance is formed from govern plus -ance, naming the activity or system of governing. It includes rules, oversight, and decision-making in a state or organization.','governance'),contexts:[C('governance.s1','机构管理','The charity published its governance rules, including who could approve spending, how conflicts were disclosed, and when trustees had to report.','慈善机构公布了治理规则，包括谁有权批准支出、如何披露利益冲突，以及受托人何时必须提交报告。','The charity published its governance rules / including who could approve spending / how conflicts were disclosed / and when trustees had to report.','governance 指治理活动及其制度安排。','审批权、监督和报告规则都属于机构治理。')],mistakes:[M('The charity’s governance had no rules, oversight, or decision-making process, though the document called it a complete system of accountability.','The charity’s governance system included rules, oversight, and decision-making procedures.','没有规则、监督或决策流程就不能称为完整治理体系。')],quiz:[Q('governance',1,1,'Governance concerns?','rules and processes for governing','the manufacture of glass','the care of a gosling','rules and processes for governing','governance 指治理制度和活动。'),Q('governance',2,1,'Good corporate governance may specify?','oversight and who can approve decisions','the colour of each cotton fibre','the height of a giraffe','oversight and who can approve decisions','治理规则包含监督和决策权。'),Q('governance',3,1,'A board reviews governance to check?','how an organization is directed and held accountable','how a glacier tastes','how to paint with gouache','how an organization is directed and held accountable','组织治理涉及管理和问责。'),Q('governance',4,1,'The suffix -ance in governance forms a noun for?','an activity or state','a young animal','a glass vessel','an activity or state','-ance 构成表示行为、状态的名词。','word-formation')]});
D('government',{etymology:E('Government is formed from govern plus -ment, through Old French governement. It means the group of people who rule a country or, more broadly, the system by which it is governed.','government'),contexts:[C('government.s1','公共政策','The government announced a flood-control plan after the river overflowed, then presented the budget to parliament for approval.','河流泛滥后，政府公布了防洪计划，随后向议会提交预算申请批准。','The government announced a flood-control plan / after the river overflowed / then presented the budget / to parliament for approval.','government 指治理国家的政府机构或执政集团。','发布公共计划并提交议会审议是政府行为。')],mistakes:[M('The government was a single private household with no authority to make public policy or administer the country.','The government was the public body responsible for administering the country.','政府是负责国家公共事务的机构，不是无公共职权的私人家庭。')],quiz:[Q('government',1,1,'A government is the group that?','rules or administers a country','makes only pottery glaze','flies an unpowered aircraft','rules or administers a country','government 指执政、治理国家的集团。'),Q('government',2,1,'A government may announce?','a public policy or national budget','a goldfish’s scale pattern','a private person’s goatee','a public policy or national budget','公共政策与预算由政府发布或提出。'),Q('government',3,1,'Citizens may elect a government to?','administer public affairs','manufacture all glassware','collect gossamer threads','administer public affairs','政府负责管理公共事务。'),Q('government',4,1,'The word government is formed from govern plus?','-ment','-ling','-like','-ment','government 由 govern 加 -ment 构成。','word-formation')]});
D('governmental',{etymology:E('Governmental is formed from government plus -al. It means relating to a country’s government or to the way the country is ruled.','governmental'),contexts:[C('governmental.s2','政治制度','The researchers compared governmental systems to see how power was divided between national leaders and regional assemblies.','研究人员比较了不同的政治治理制度，以了解国家领导层与地区议会之间如何分配权力。','The researchers compared governmental systems / to see how power was divided / between national leaders / and regional assemblies.','governmental 在此表示与国家统治方式或政治制度有关。','比较权力分配方式，符合 s2。')],mistakes:[M('The report described a household recipe as governmental even though it concerned no state, public authority, or system of rule.','The report described the household recipe as domestic rather than governmental.','家常食谱不涉及政府或国家统治，不能称 governmental。')],quiz:[Q('governmental',1,1,'A governmental office is?','connected with a country’s government','a small valley in Scotland','a type of fish','connected with a country’s government','s1 指政府的、与政府有关的。'),Q('governmental',2,2,'Governmental structure concerns?','how a country is ruled and power is organized','how a ceramic bowl is glazed','how a goose grows','how a country is ruled and power is organized','s2 指国家统治和权力安排。'),Q('governmental',3,1,'Which document is governmental?','a ministry’s official policy notice','a private picnic invitation','a lab note on glucose','a ministry’s official policy notice','政府部门发布的政策通知属于 governmental。'),Q('governmental',4,2,'A study of governmental systems compares?','forms of political rule','types of cotton checks','giraffe feeding habits','forms of political rule','国家政治制度比较属于该词范围。')]});
D('governor',{etymology:E('Governor comes through Old French governour from Latin gubernator, “steersman” or “ruler,” from gubernare “to steer.” It names a state or territorial leader and also a device that regulates engine speed.','governor'),contexts:[C('governor.s2','机械维修','The mechanic replaced the governor because the engine kept racing above its safe speed whenever the load suddenly decreased.','发动机负载突然减轻时，转速总会超过安全范围，因此机械师更换了调速器。','The mechanic replaced the governor / because the engine kept racing / above its safe speed / whenever the load suddenly decreased.','governor 在此是控制发动机转速的调节器。','负载变化时限制转速的装置对应 s2。')],mistakes:[M('The mechanic removed the governor to make the engine speed automatically stay within a safe limit.','The mechanic repaired the governor so it could regulate the engine speed.','拆除调速器不会让它发挥限速作用。')],quiz:[Q('governor',1,1,'A US state governor is?','the elected head of the state','a cotton-separating machine','a kind of glass paint','the elected head of the state','s1 指美国州长。'),Q('governor',2,2,'An engine governor controls?','the engine’s speed','the colour of its fuel','the number of its passengers','the engine’s speed','s2 指发动机调速器。'),Q('governor',3,1,'A governor sent to a territory may?','administer it on behalf of a larger state','shape a ceramic bowl','catch fish with a net','administer it on behalf of a larger state','governor 也可指受派治理属地的人。'),Q('governor',4,2,'If an engine overspeeds, a faulty governor may have failed to?','regulate its speed','paint the body','filter its oil into glass','regulate its speed','调速器故障会无法控制发动机转速。')]});
D('gown',{etymology:E('Gown came through Old French goune from a Germanic word for a garment. It can mean a long formal dress, a robe worn by judges or academics, or a loose garment worn at home or in bed.','gown'),contexts:[C('gown.s2','毕业典礼','The professor adjusted her academic gown and hood before joining the graduates for the formal procession across the hall.','教授在加入毕业生、穿过大厅参加正式列队前，整理了学术长袍和垂布。','The professor adjusted her academic gown and hood / before joining the graduates / for the formal procession / across the hall.','gown 在此指学者穿的宽松礼袍。','教授参加正式仪式并佩戴学术垂布，符合 s2。')],mistakes:[M('The judge entered court in a short bathing suit instead of the loose robe traditionally worn for the hearing.','The judge entered court in a formal judicial gown.','法官参加正式庭审时通常穿袍服，而不是泳衣。')],quiz:[Q('gown',1,1,'A formal evening gown is?','a long dress for a special occasion','a small glass bottle','a type of freshwater fish','a long dress for a special occasion','s1 指正式场合的长礼服。'),Q('gown',2,2,'A judge’s gown is?','a loose robe worn in court','a cotton gin','a sleeveless fish scale','a loose robe worn in court','s2 指法官、学者等穿的袍服。'),Q('gown',3,3,'A dressing gown is worn?','at home or in bed','only while governing a state','to protect eyes while swimming','at home or in bed','s3 指居家或睡觉时穿的睡袍。'),Q('gown',4,2,'Which person might wear an academic gown?','a professor at a formal ceremony','a goldfish in an aquarium','a glassmaker at a furnace','a professor at a formal ceremony','学者参加正式典礼会穿学术袍。')]});
D('gp',{etymology:E('GP is an abbreviation of general practitioner. In British English it commonly means a doctor who provides general medical care rather than specializing in one hospital department.','gp'),contexts:[C('gp.s1','基层医疗','After the cough persisted for a week, Owen booked an appointment with his GP, who examined his chest and arranged a follow-up.','咳嗽持续一周后，欧文预约了全科医生；医生检查了他的胸部并安排复诊。','After the cough persisted for a week / Owen booked an appointment with his GP / who examined his chest / and arranged a follow-up.','GP 是 general practitioner 的缩写，常指英国基层全科医生。','就常见症状提供初诊和后续安排符合全科医生职责。')],mistakes:[M('Owen booked a GP appointment to have his car engine regulated by a general practitioner.','Owen booked a mechanic’s appointment to have his car engine regulated.','GP 是医生，不是汽车机械师。')],quiz:[Q('gp',1,1,'In Britain, a GP is a?','general doctor','glassmaking professional','governmental parliament','general doctor','GP 指全科医生。'),Q('gp',2,1,'Someone with a persistent cough might first contact?','their GP','a goldsmith','a glider','their GP','基层全科医生可处理常见健康问题。'),Q('gp',3,1,'GP is short for?','general practitioner','gossamer pilot','glacial process','general practitioner','GP 是 general practitioner 的缩写。','meaning'),Q('gp',4,1,'A GP usually provides?','general medical care','engine-speed regulation','gown tailoring only','general medical care','全科医生提供一般医疗服务。')]});
D('grab',{etymology:E('Grab is recorded in English from the late Middle Ages, probably from a Germanic source related to grasp. It means seize suddenly, take roughly, or quickly take an opportunity; it can also name a sudden attempt to take hold.','grab'),contexts:[C('grab.s3','把握机会','When the scholarship portal reopened for one afternoon, Mei grabbed the chance to submit the application she had finished the night before.','奖学金申请系统只在一个下午重新开放，梅抓住机会提交了前一晚已完成的申请。','When the scholarship portal reopened for one afternoon / Mei grabbed the chance / to submit the application / she had finished the night before.','grab 在此指迅速把握机会。','系统短暂开放，她立即提交申请，符合 s3。')],mistakes:[M('When the scholarship portal reopened briefly, Mei grabbed the chance by ignoring it and submitting nothing.','When the scholarship portal reopened briefly, Mei missed the chance by submitting nothing.','完全没有利用机会不能称为抓住机会。')],quiz:[Q('grab',1,1,'To grab a handle is to?','take hold of it suddenly','polish it with a glaze','measure its weight','take hold of it suddenly','s1 指突然抓住某物。'),Q('grab',2,2,'To grab a bag from someone roughly is to?','take it by force','return it politely','make it from glass','take it by force','s2 表示粗暴抢夺。'),Q('grab',3,3,'To grab an opportunity is to?','take advantage of it quickly','wait until it has passed','turn it into a glider','take advantage of it quickly','s3 指迅速把握机会。'),Q('grab',4,4,'A sudden grab for a wallet is?','an attempt to seize it','a planned glassmaking process','a government policy','an attempt to seize it','s4 可作名词指突然伸手抓取。')]});

})();
